/* Patient counselling: choices, expected course, recovery and recurrence.
 * Intervention flows also cover preparation, immediate follow-up and aftercare.
 * Profiles are shared only by explicitly listed, clinically related records.
 * Time ranges are counselling estimates, never automatic stop-drug dates.
 */
(function (root) {
  'use strict';
  var diseases = {}, procedures = {};
  function profile(options, course, outlook, recurrence) {
    return {options: options, course: course, outlook: outlook, recurrence: recurrence};
  }
  function assign(target, value, ids) {
    ids.trim().split(/\s+/).forEach(function (id) {
      var range = id.match(/^([dp])(\d+)-(?:[dp])?(\d+)$/);
      var keys = range ? Array.from({length: Number(range[3]) - Number(range[2]) + 1}, function (_, i) { return range[1] + (Number(range[2]) + i); }) : [id];
      keys.forEach(function (key) {
        if (target[key]) throw new Error('Duplicate patient education profile: ' + key);
        target[key] = value;
      });
    });
  }
  function d(ids, options, course, outlook, recurrence) { assign(diseases, profile(options, course, outlook, recurrence), ids); }
  function p(ids, options, course, outlook, recurrence) { assign(procedures, profile(options, course, outlook, recurrence), ids); }

  d('d0 d2 d352', '先補充人工淚液、改善環境與眼表發炎；較嚴重時可選處方抗發炎眼藥、淚點處置或其他眼表修復治療。若有自體免疫病，也需一起控制。', '潤滑可能較快減輕不適，處方抗發炎藥常要數週至數月評估效果；多數需長期維持，並非點完一瓶就結束。', '多數能減輕乾澀及視力波動；淚腺受損較重時，目標是保護角膜與維持舒適，不能保證恢復正常淚量。', '乾燥、長時間用眼或全身病活動時容易再加重；改善後仍需持續適合自己的保養。');
  d('d1 d7 d317', '以安全溫敷、眼瞼清潔和潤滑為基礎；視發炎程度加入處方眼藥、口服藥或腺體治療，並處理酒糟或皮膚問題。', '通常需持續數週才較明顯改善，常以約 2–8 週觀察反應；之後依症狀調整為長期保養。', '治療能改善油脂排出與不適，但已萎縮的腺體不一定恢復；角膜若已有疤痕，視力改善也會受限。', '屬容易反覆的慢性問題；停止清潔、熬夜或皮膚發炎時可能再發。');
  d('d3 d326', '先用人工淚液、睡前眼藥膏及保濕保護；若閉眼功能無法改善，可選暫時縫合眼瞼、配重或眼瞼重建。', '輕微表皮傷口可能數日改善，但保護措施需持續到眼瞼能安全閉合；神經或結構問題可能需數月或長期照護。', '及早保護通常可避免潰瘍；若已感染、結疤或穿孔，恢復較久且可能留下視力影響。', '閉眼不全仍存在時，角膜仍可能再受傷；睡眠期間也不能省略保護。');
  d('d4', '減少刺激性眼藥並積極潤滑；依傷口可選血清製劑、保護鏡片、神經生長因子治療、羊膜或眼瞼縫合等方式。', '表皮癒合常需數週至數月；即使傷口閉合，也要繼續追蹤感覺與眼表，不能依不痛自行停藥。', '治療目標先讓角膜完整、避免穿孔；感覺及透明度不一定完全恢復，疤痕可能限制視力。', '神經功能未恢復時容易反覆破皮；新白點、混濁或視力變差即使不痛也要回診。');
  d('d5', '先改善乾眼與發炎，醫師可移除細絲；反覆者可評估黏液調整藥、保護鏡片或其他眼表治療。', '移除後摩擦感可能較快減輕，但眼表穩定通常需數週，較嚴重乾眼可能需長期治療。', '細絲清除後多能舒適一些；若乾眼、眼瞼或角膜病因未改善，單次移除不代表治癒。', '相當容易再長，需持續處理眼表病因，不自行拉除。');
  d('d6', '先潤滑並控制眼表與甲狀腺相關問題；頑固病例可討論保護鏡片、局部藥物或選定的結膜處置。', '常以數週觀察初步反應；反覆摩擦或相關疾病未穩定時，可能需數月以上照護。', '多能控制不適，但通常不是一次點藥就永久消失；治療依摩擦來源及眼表狀況調整。', '乾眼與摩擦持續時可能復發，症狀改善後仍要保養。');
  d('d8', '由醫師補足維生素 A，同時治療營養不足或吸收不良；有角膜傷口時需加強潤滑、抗感染及必要的修復。', '夜視改善可能較早出現，眼表修復常需數週；若吸收問題持續，營養監測與補充需更久。', '缺乏及早處理通常較能恢復；已造成角膜軟化、疤痕或其他組織損害時可能留下永久影響。', '營養或吸收病因未改善會再缺乏；高劑量補充須監測，不自行長期服用。');
  d('d9 d16', '若確認角膜感染，以合適抗生素眼藥控制，必要時採檢或住院；非感染性鏡片發炎則需重新評估，不是一律使用同一種藥。', '嚴重感染初期可能連夜密集點藥，數日內檢查反應；完整療程常需數週，深部或大潰瘍可能更久。', '小而周邊的病灶通常較有機會保留視力；中央、深層感染即使控制也可能留疤，少數需修補或角膜移植。', '接觸鏡衛生、碰水或眼表問題未改善可再次感染；須確認痊癒後才恢復配戴。');
  d('d10', '依採檢與病原使用抗黴菌眼藥，部分需口服、注射或治療性角膜移植；不能只用一般抗生素處理。', '通常需數週至數月，早期可能頻繁回診；症狀變輕不代表深部病原已清除。', '病灶深度、位置與開始治療的時間影響結果；可能留下疤痕，嚴重者有穿孔或視力永久受損風險。', '療程不足或仍有深部感染可再惡化；停藥須依角膜檢查，不自行決定。');
  d('d11', '活動性表皮感染通常使用抗病毒眼藥或口服藥；反覆發作或特定高風險情況可討論預防性口服治療。', '單純表皮病灶多以約 1–2 週為初步治療範圍，較大或癒合不良會更久；預防療程可達數月以上。', '及早控制通常可癒合；反覆發作可能降低角膜感覺並留下混濁，影響視力。', '病毒可潛伏後再活化，因此有復發可能；新的紅痛、畏光或模糊應提早檢查。');
  d('d12', '通常以抗病毒藥搭配醫師監測下的抗發炎治療；若有高眼壓也需控制。類固醇減量速度由發炎反應決定。', '常需數週至數月控制及慢慢減藥；部分患者需更長預防性抗病毒療程。', '水腫與發炎消退後視力可能改善；反覆發作留下的基質疤痕或內皮損傷不一定恢復。', '可能反覆，減藥過快或自行只用類固醇都可能使病情失控。');
  d('d13', '及早使用全身抗病毒藥，眼表、眼內發炎與眼壓另依檢查治療；神經痛可能需其他止痛處理。', '急性抗病毒療程通常約一週左右，依免疫與病情調整；眼部發炎及神經痛可能持續數月。', '皮疹好轉不代表眼內完全穩定；部分可有角膜疤痕、感覺下降或慢性疼痛。', '之後仍可能再有角膜或眼內發炎；反覆病例可討論延長抗病毒及疫苗相關安排。');
  d('d14', '以抗棘阿米巴眼藥長期治療，部分需合併藥物；嚴重疼痛、難治感染或疤痕可能要進一步處置。', '常需數月，部分超過半年；初期密集點藥，之後依角膜反應逐步調整。', '早期診斷較有利；深層感染可能留下嚴重疤痕，必要時評估角膜移植，視力未必完全恢復。', '病原可形成較耐受型態，停藥後可能再活化；須完成醫師安排的觀察與療程。');
  d('d15', '表淺與基質感染需分開處理；可選支持照護、適當抗感染治療或病灶處置，深層難治病例可能需移植。', '表淺病變可能數週改善，基質感染可拖延數月；療程依侵犯深度與採檢結果決定。', '表淺型較有機會恢復透明；深部病灶較容易留下疤痕與視力損害。', '持續感染、免疫或眼表問題可能造成復發；避免再次暴露不潔水源。');
  d('d17', '先找出感染或免疫病因，再選全身抗感染、抗發炎與眼表治療；合併聽力問題時也需耳鼻喉或相關專科。', '常需數週至數月；有全身免疫病者可能要長期控制，病原治療另有完整療程。', '活動性發炎可改善，但已形成的角膜血管與疤痕可能持續影響視力。', '是否再發取決於原病因；全身病控制不穩或療程中斷會增加風險。');
  d('d18 d353', '通常以潤滑、短期抗感染預防與適當止痛為主；較大或特殊傷口可能需保護鏡片並密切回診。', '小而表淺、沒有感染的擦傷常在約 1–3 天修復；較大傷口可能需更久，24–48 小時未改善應重新檢查。', '單純擦傷多可恢復原視力；深層傷、感染或上皮附著不良可能留下疤痕或反覆破皮。', '新生表皮有時附著不牢，之後清晨可能再痛；需要時持續潤滑數月。');
  d('d19 d20', '先潤滑與睡前保護；若反覆破皮，可選保護鏡片、表面清創、拋光、雷射或適當位置的基質穿刺。', '急性破皮常數日減輕，讓表皮附著穩定通常需數月保養；介入後也要等待上皮癒合與視力穩定。', '多數可減少疼痛發作；中央疤痕或不規則散光可能使視力恢復較慢。', '本來就容易再發，即使手術後仍可能需要潤滑或再次處置。');
  d('d21 d354', '由醫師確認深度後移除異物與必要鏽環，並保護表皮；高速或疑似穿入者需先檢查眼內異物。', '表面異物取出後，小傷口常數日癒合；深層損傷、鏽環或感染會延長到數週以上。', '周邊淺層傷多預後良好，中央或深部傷可能留疤；穿入眼內的情況需另評估。', '異物未清除或工作暴露持續可能再次發生；痊癒後少數會反覆糜爛。');
  d('d22 d23 d24', '依深度先選眼鏡或特殊鏡片；疼痛可用眼表治療，影響視力的淺層沉積可評估雷射，較深者可能需角膜移植。', '沒有短期藥物能清除遺傳沉積；雷射後恢復約數週，移植後常需數月以上，並持續長期追蹤。', '治療可改善透明度或疼痛，但效果受沉積深度、角膜不規則與其他眼病影響。', '遺傳病因仍存在，沉積可能在原角膜或移植物再次出現，未必一次手術就永久解決。');
  d('d25 d32', '輕度可先以眼藥緩解水腫及疼痛；內皮無法維持透明時，可評估內皮移植，部分需合併白內障處理。', '眼藥多是暫時緩解，不能補回失去的內皮；移植後視力常在數週至數月改善，抗排斥與眼壓追蹤更久。', '若其他眼部構造健康，移植可明顯改善混濁；長期水腫、疤痕或視神經病會限制改善。', '水腫可反覆，移植後也可能排斥或再次失能；紅、痛、畏光或變糊要儘早回診。');
  d('d26', '依混濁、眼壓及視覺發展選擇觀察、配鏡、弱視治療或角膜移植；有青光眼時需另外控制。', '輕症可能追蹤多年；手術恢復需數週至數月，兒童視覺訓練與眼壓監測通常更長。', '視力除了角膜透明度，也受早期弱視影響；即使移植透明也不一定達正常視力。', '發育或遺傳差異不會因手術完全消失，需留意移植物與青光眼的後續變化。');
  d('d27 d28', '眼鏡或特殊接觸鏡改善視力；確認持續擴張時評估交聯，特定病例可選角膜環或移植。不同變薄型態適用性不同。', '鏡片驗配可能需數次調整；交聯後表皮數日修復、視力穩定常需數月，之後仍長期比較角膜形狀。', '目標分成讓角膜穩定與改善視力；交聯不保證把角膜變回正常形狀，嚴重疤痕可能需移植。', '角膜仍可能進展，尤其持續揉眼或過敏未控制時；需持續追蹤而非只看度數。');
  d('d29', '不影響視力的沉積多可觀察；有表面不平、疼痛或視軸混濁時，可選清除沉積、表面處理或其他手術。', '無症狀者沒有必須完成的療程；表面處置後常需數日至數週癒合，深層或變薄病灶需更久追蹤。', '預後取決於退化類型與是否影響中央角膜；有些外觀變化不影響視力。', '沉積、發炎或代謝原因仍在時可能再長；變薄型病灶仍須防撞與監測。');
  d('d30 d51', '先區分感染及免疫性破壞；除局部保護外，可能需全身免疫或抗感染治療，快穿孔時以組織膠或移植物修補。', '急性期可能需每日或很密集檢查；控制發炎常要數週至數月，全身疾病通常需長期照護。', '先保住眼球結構，再考慮視力；變薄、疤痕與穿孔可留下永久影響。', '原本血管炎或免疫病可能再活躍，眼部平靜後仍不能自行停全身治療。');
  d('d31', '由醫師核對局部與全身用藥，減少刺激或改用替代藥，並潤滑、處理表皮傷口；必要的全身藥須與原團隊協調。', '表面刺激可在調整後數日至數週改善；藥物沉積或深部損傷消退可能需數月，部分無法完全消失。', '單純沉積不一定影響視力；若已造成表皮缺損、神經損傷或疤痕，恢復較慢。', '再次接觸同類毒性或刺激物可能復發，需保留確定的藥物反應紀錄。');
  d('d33', '儘快確認排斥並加強醫師處方的抗發炎藥，必要時全身治療；同時排除感染及監測眼壓。', '通常需密集治療數日後檢查，之後數週至數月逐步調整；維持性藥物常需更久。', '早期治療較可能挽救透明度；若內皮或移植物已不可逆失能，可能需再次移植。', '任何時期都可能再排斥；不因移植多年或視力穩定就自行停藥。');
  d('d34', '一般細菌性病例可依嚴重度選觀察、清潔或抗生素眼藥；大量膿液疑似淋病時需緊急全身治療與角膜評估。', '輕症常數日至一兩週改善；特定病原需完整專用療程，不能用一般紅眼的時間預期等待。', '單純結膜感染多能恢復；若病原快速侵犯角膜，可能嚴重影響視力。', '再次接觸、眼瞼感染或相關性傳染病未處理會再發，並需避免傳給他人。');
  d('d35', '以冷敷、人工淚液與衛生措施為主；抗生素不能治療腺病毒。角膜嚴重發炎時才由眼科評估特殊藥物。', '紅眼通常約 1–3 週逐漸減輕；若有角膜浸潤，模糊或眩光可能持續數月。', '多數視力能恢復；角膜病灶有時恢復慢，症狀嚴重或持續應再確認病因。', '角膜免疫反應可反覆，不一定代表仍具同樣傳染力；仍要避免共用毛巾與污染眼藥。');
  d('d36', '成人披衣菌通常需全身抗生素並安排伴侶治療；砂眼依感染、疤痕及倒睫程度選藥物、衛生措施或手術。', '用藥療程依病原與製劑決定；紅眼常需數週消退，既有眼瞼疤痕的處理可能更久。', '清除感染可改善發炎，但角膜與眼瞼疤痕不一定逆轉；需另處理倒睫及視力問題。', '未治療的接觸者或重複暴露會造成再感染，單治療眼睛可能不足。');
  d('d37 d38 d39 d40', '先避免揉眼與相關過敏原或機械刺激，選冷敷、潤滑及抗過敏眼藥；反覆或侵犯角膜者可加專科抗發炎或免疫調節治療。', '止癢可能數日見效，控制眼表發炎常要數週；慢性或季節性病況可能需跨季節、數月以上維持。', '單純過敏多可控制且不影響永久視力；角膜潰瘍或長期疤痕會增加視力風險。', '接觸刺激物或過敏體質仍在時容易再發；接觸鏡相關者須調整驗配與清潔方式。');
  d('d41', '眼表潤滑外，多需全身免疫調節藥減少結疤；眼瞼或角膜重建需在疾病適當控制後規劃。', '通常需數月評估控制，之後可能多年維持；要監測血液、肝腎功能及藥物副作用。', '目標是阻止繼續結疤；已形成的沾黏、乾眼或角膜損害不一定能逆轉。', '症狀很輕也可能持續進展，減停藥後可能再活化，需由專科判斷。');
  d('d42', '急性期需停用確定可疑藥物並住院跨科治療；眼部以密集保護、抗發炎及適合時機的羊膜等方式減少損傷。', '急性恢復常需數週；眼表乾燥、疤痕與睫毛問題可持續數月甚至多年。', '早期眼部照護很重要，重症仍可能留下嚴重乾眼及角膜疤痕，需分階段重建。', '再接觸致病藥可能再發嚴重反應；即使沒有新全身發作，慢性眼表問題仍會反覆。');
  d('d43', '先確認纖溶相關病因，可選專科局部或全身治療及必要的膜處理，不能只反覆撕除。', '常需長期控制，局部病灶處理後數週內仍要追蹤是否重新形成。', '可減少厚膜與刺激，但病因未矯正時很難靠單次處置根治。', '容易在發炎或操作後再形成厚膜；需持續全身與眼部追蹤。');
  d('d44', '依貓抓病等確定病因決定抗感染或觀察，淋巴結與眼部需一起評估。', '改善常以數週計，淋巴結腫大可能更久；療程由病原、全身及眼部侵犯決定。', '多數病因經適當處理可改善，但若影響視神經或視網膜，視力恢復需另評估。', '原感染未控制或再次暴露時可再發，需依動物接觸與全身症狀追蹤。');
  d('d45', '輕症先防曬、潤滑；持續發炎或影響角膜形狀及視軸時可切除並合併結膜移植。瞼裂斑不一定需要手術。', '手術後表面多在數週修復，紅眼與度數穩定可能更久；點藥與追蹤依傷口調整。', '能減少病灶造成的刺激及部分散光；中央疤痕或其他眼病仍可能限制視力。', '翼狀贅片可能再長，防曬與控制眼表發炎有助後續照護，復發可能需再次處理。');
  d('d46', '無症狀可觀察；露出表面且磨到角膜時，由醫師在局部麻醉下移除。', '小範圍移除後不適常數日改善；若合併眼瞼發炎，保養需更久。', '通常預後良好，處置目的主要是減少摩擦，不是提升本來已正常的視力。', '其他沉積點可能逐漸露出，也可能再形成，不需把所有無症狀小點都挖除。');
  d('d47', '單純結膜下出血通常觀察即可，乾澀可潤滑；反覆時檢查血壓、用藥與出血傾向。', '常約 1–2 週逐漸吸收，範圍大時更久，顏色改變不一定代表惡化。', '沒有疼痛、外傷或其他眼病的單純出血，通常不留下視力影響。', '咳嗽、揉眼、血壓或用藥因素仍在時可能再發；抗凝血藥不要自行停用。');
  d('d48', '輕症可潤滑、冷敷或觀察；較不適時由醫師選抗發炎治療，反覆者評估全身疾病。', '常在一兩週內改善，但不同發作可能持續較久；未改善或疼痛加重需再檢查。', '單純表層發炎多不影響永久視力；需確認不是較深層的鞏膜炎。', '可能反覆發作，尤其合併免疫或其他發炎性疾病時。');
  d('d49 d50', '先分辨感染與免疫性原因，可能需口服抗發炎、類固醇或免疫藥；感染型需要對應抗感染治療。', '通常需數週至數月，重症或全身疾病可能長期治療；疼痛改善後仍需確認深層發炎已穩定。', '早期治療能降低結構損傷；壞死、視網膜或視神經受累時可能留下視力問題。', '可復發，復發時須重新排除感染及全身病活動，不能只沿用舊眼藥。');
  d('d52', '先找出是否為年齡、結締組織、骨骼或其他病因；不影響功能的外觀變化可能不需眼部治療。', '沒有統一的短期療程；若是組織結構特性，需長期防護與依病因追蹤。', '顏色本身不等於視力差，預後取決於眼球脆弱度及相關全身病。', '結構性顏色通常持續存在，重點是防外傷及監測，而非反覆用藥去除藍色。');
  d('d53', '以眼鏡或接觸鏡矯正；兒童可依條件選近視控制眼藥或鏡片。成人度數穩定後可評估屈光手術，但仍需眼底照護。', '矯正可立即改善對焦，兒童近視控制通常需數年並定期評估，並非數週就能治好近視。', '近視度數可被矯正，但眼軸過長及高度近視的眼底風險不會因雷射消失。', '成長期可能繼續加深，成人也可能變化；近視控制或手術後仍需定期檢查。');
  d('d54 d55 d57', '先以正確眼鏡或接觸鏡讓影像清楚，特殊不規則或差異過大時再討論其他方式；兒童需留意弱視與眼位。', '通常需數日至數週適應新鏡片；兒童須隨成長追蹤，屈光狀態可能多年變動。', '單純屈光異常大多可改善清晰度；若已有弱視、角膜或視網膜疾病，最佳視力可能受限。', '眼鏡矯正的是對焦，不會永久消除所有度數；後續仍可能需調整。');
  d('d56', '依需求選閱讀眼鏡、多焦眼鏡或接觸鏡；手術或藥物僅適合部分患者，需比較遠近視覺、乾眼與夜視取捨。', '眼鏡適應常為數日至數週；老花會隨年齡逐步變化，之後可能要調整近用需求。', '多數可讓近距離活動更方便，但無法讓原水晶體恢復年輕時的所有調節功能。', '屬年齡相關變化，不是短療程治癒；即使手術後仍可能在某些距離需要眼鏡。');
  d('d58 d285-d288', '先戴足夠矯正的眼鏡，依單眼視力反應加入遮眼、藥物或其他適合的弱視治療；阻擋視軸的病因需先處理。', '視力改善常要數週至數月，完整治療可能更久；依年齡及反應逐步調整，不能只照固定時數做到底。', '越早發現通常越有利；治療目標是改善較弱眼的視覺發展，斜視或白內障手術本身不等於弱視治癒。', '減量或停治療後可能再下降，仍需追蹤單眼視力；勿自行突然停止或過度遮眼。');
  d('d59 d60 d62', '確認度數與眼表，調整用眼及休息；依調節檢查可選近用加光、特定訓練或醫師處方藥，不是所有疲勞都需要同一治療。', '習慣與矯正調整後可在數日至數週改善，訓練常需數週以上；持續症狀要重新找病因。', '多數可改善舒適度，但效果取決於是否有真正的調節異常、乾眼或其他疾病。', '長時間近距離、不合適度數或誘因持續時可能再發，需維持合適工作距離與休息。');
  d('d61 d298', '先矯正度數，符合有症狀集合不足者可選系統性集合訓練；部分可用稜鏡或其他個別處置。', '訓練通常以數週至數月評估，並依症狀與檢查調整，不是一兩次就判定有效。', '適當選例可改善閱讀不適及複視；不是用來治療所有斜視或取代其他神經檢查。', '停訓、疲勞或用眼負荷增加時可能再不適，必要時安排維持訓練或再評估。');
  d('d63 d64 d65', '先停戴並檢查是否感染，處理乾眼或藥水刺激，再重新驗配、改配戴時間或換清潔系統；眼鏡是安全替代方式。', '單純刺激可能數日至數週改善，缺氧血管或嚴重眼表損傷需更久；恢復配戴須確認角膜穩定。', '多數不適可改善，但既有新生血管、疤痕或感染不一定完全消失。', '若繼續過久配戴、碰水或使用不相容藥水，問題容易再發。');
  d('d66', '依閱讀、移動與工作需求選放大鏡、電子輔具、照明、行動訓練及社會支持；同時治療仍可改善的眼病。', '初步評估與試用可分數次進行，適應與訓練常需數週至數月，需求改變時再調整。', '目標是提高生活功能與獨立性，不是讓已受損組織重新長回；仍可能有很實際的改善。', '不是典型復發性疾病；原病進展或生活需求改變時，需要重新配適與復健。');
  d('d67 d71 d72', '先依眼壓、視神經、隅角與家族風險選擇規律觀察；風險較高或有變化時，才評估眼藥或適合的預防雷射。', '通常是長期監測，回診間隔依風險訂定；不是每次偏高或隅角偏窄都需要立刻手術。', '不少人可多年維持穩定，但不能用目前沒症狀保證未來不進展。', '風險仍會隨年齡與眼部狀況改變，需要持續比較檢查。');
  d('d68-d70 d79 d80 d87 d94 d361', '依眼壓目標可選眼藥、適合的隅角雷射或手術，藉減少房水生成或增加排出來保護視神經。', '多屬長期甚至終生控制；換藥或雷射後要數週評估反應，手術後前幾週至數月回診較密。', '治療主要保住尚存的視野，已失去的視神經功能通常無法恢復；達標後仍要追蹤是否進展。', '不是短期治癒後就無風險；雷射效果可減弱、手術通路可結疤，可能需再加藥或再次處置。');
  d('d73 d74 d76 d77', '依阻塞機轉可選虹膜雷射、降眼壓藥、水晶體手術或其他青光眼手術；高原虹膜可能需要不同輔助處置。', '雷射多為門診處置，後續數日到數週檢查眼壓與隅角；若已有青光眼，需長期控制與視野追蹤。', '解除阻塞可減少發作及壓力，但既有沾黏、視神經損害不一定逆轉。', '雷射後仍可能有殘留閉鎖或再升壓，不能把做過雷射當成永久免追蹤。');
  d('d75', '立即用適當藥物降低眼壓並控制疼痛，再依機轉做虹膜雷射或其他處置；也要評估另一眼是否需預防。', '急性降壓按小時處理，之後數日到數週密切追蹤；穩定後仍可能需水晶體或長期青光眼治療。', '越早解除高眼壓越有利；拖延可能造成永久視力及視野損害，疼痛減輕不等於完全安全。', '未解除阻塞機轉或仍有隅角沾黏時可能再發；同時要照護另一眼。');
  d('d78', '以調整房水流向的藥物處理，必要時依眼睛有無水晶體選雷射或玻璃體相關手術，與一般瞳孔阻滯不同。', '急性期需立即處理及密切檢查，穩定可能需數日至數週；部分需較長用藥或再次手術。', '前房與眼壓可改善，但預後取決於持續時間及角膜、視神經原先狀態。', '可能復發，尤其流向異常未完全解除時；不自行加縮瞳藥或停藥。');
  d('d81', '同時處理視網膜缺血與眼壓，可選抗血管新生注射、視網膜雷射、眼藥及青光眼手術。', '注射可較快壓低新生血管，但作用有限期；雷射、手術與原疾病控制需數週至數月，之後仍長期追蹤。', '可減輕疼痛並保護剩餘視力；嚴重視網膜缺血及視神經損害常限制恢復。', '缺血原因仍在時血管可能再長、眼壓再升，不能只靠一次注射。');
  d('d82 d118', '發作時降低眼壓與控制發炎，部分需檢查病毒並給特定抗病毒治療；反覆損傷可再評估青光眼手術。', '單次發作常需數日至數週控制；有病毒或反覆發作時，療程及預防可能更久。', '初期常可恢復，但多次高眼壓仍可能造成青光眼性損害。', '有再發可能，即使平常不紅不痛也應追蹤眼壓與視神經。');
  d('d83 d117', '視情況處理白內障與眼壓；低度慢性發炎不一定需長期類固醇，治療須與一般急性虹彩炎區分。', '通常長期追蹤；白內障或青光眼介入的恢復需數週，並非用一段抗發炎眼藥即可結束。', '可治療併發症以維持視力；視神經已受損或其他混濁時改善會受限。', '低度發炎可能持續存在，之後仍可能有白內障或眼壓問題。');
  d('d84', '同時控制眼內發炎與眼壓，依病因選抗感染、免疫藥、降眼壓藥或手術，不宜只處理其中一項。', '急性期數日到數週調整，慢性免疫或病毒問題可能需數月以上；眼壓與藥物副作用都要監測。', '充分控制可降低傷害，但沾黏、角膜與視神經損害可能留下永久影響。', '發炎再活躍、類固醇反應或手術疤痕都可能讓眼壓再升。');
  d('d85', '與原開藥團隊調整類固醇，必要時換藥並加降眼壓治療；嚴重或持續者再評估雷射或手術。', '藥物調整後眼壓可能數日至數週下降，長效注射或植入藥可能影響更久；仍須持續量眼壓。', '及早發現可避免視神經損害；已造成青光眼的部分不一定隨停藥恢復。', '再次使用類固醇仍可能升眼壓，需主動告知既往反應。');
  d('d86 d88', '先降眼壓與控制發炎，再依原因處理病變水晶體、殘留碎片或舊積血；有時需玻璃體或水晶體手術。', '急性高壓需立即處理，病因清除及恢復常以數週計，後續再確認能否減少降眼壓藥。', '移除原因後可能改善；若高壓已久、角膜或視神經已受損，視力不一定完全恢復。', '殘留病因、再出血或永久排水損傷仍可能讓眼壓再升。');
  d('d89 d90 d91 d92 d95 d96', '先釐清角膜、手術、腫瘤、血管或發育病因，再個別選眼藥與手術；腫瘤相關者必須先與眼腫瘤團隊規劃。', '通常需長期監測，術後前數週較密集；兒童與複雜構造可能要多次調整或手術。', '目標是維持剩餘視功能及眼球舒適，結果受原病與角膜、視神經狀態影響。', '結構差異或原病仍在，眼壓可能再次失控；即使手術成功仍需追蹤。');
  d('d93 d306', '多以打開異常排水構造的手術為主，眼藥可作輔助；同時矯正度數及治療弱視。', '手術後數週至數月需密集評估，之後追蹤延續整個成長期甚至終生，可能需再次手術。', '早期降壓有助保護視神經與角膜，但已發生的視神經損害及弱視會限制視力。', '眼壓可再升，眼球不再變大或不流淚不代表已永久治癒。');
  d('d97-d103', '早期可調眼鏡與照明；白內障已明顯影響生活時，以手術移除混濁水晶體並植入人工水晶體，眼藥無法把它變透明。', '白內障本身通常逐漸變化，沒有固定需等多久；手術後數日可開始改善，眼睛癒合與度數穩定多需約 4–8 週。', '若視網膜、角膜與視神經健康，通常有良好改善機會；多焦或其他鏡片也各有光學取捨，仍可能需要眼鏡。', '移除的白內障不會重新長回，但保留的後囊可能日後混濁，必要時再做雷射。');
  d('d104', '確認模糊確由後囊混濁造成後，可用 Nd:YAG 雷射開一個透明通道；不是再把人工水晶體取出。', '通常門診一次完成，視覺可能數日改善；仍依眼壓及眼底狀況安排短期檢查。', '若沒有其他眼病，多可改善混濁所致視力；黃斑或視神經問題不會因後囊雷射消失。', '同一開口通常可維持，但少數需擴大；新模糊仍要找原因，不能一律認為又是後囊。');
  d('d105 d305', '依混濁是否阻擋視覺發展決定觀察或及早手術，之後用眼鏡、接觸鏡或合適人工水晶體矯正並治療弱視。', '手術傷口恢復以數週計，但視覺發展與弱視治療常需數年；必須長期監測眼壓。', '及早讓影像清楚較有利，視力仍受先天病因、手術時機與弱視程度影響。', '可出現再次視軸混濁或多年後青光眼，手術完成不代表停止追蹤。');
  d('d106 d362', '先確認眼球完整與其他外傷，依囊袋及水晶體狀態選手術及人工水晶體固定方式，有時需分期。', '急症先處理，穩定後手術與恢復常需數週至數月；兒童另外需要長期弱視照護。', '去除混濁可改善對焦，但視網膜、角膜或視神經外傷可能限制最終視力。', '外傷造成的眼壓、囊袋或鏡片位置問題可能稍後出現，需長期追蹤。');
  d('d107 d108 d363', '輕度可先用鏡片矯正並追蹤；若有明顯偏位、眼壓或發炎問題，可能需移除水晶體與另行固定人工水晶體。', '急性疼痛或高眼壓要立即處理；手術後穩定常需數週至數月，先天疾病還需全身長期照護。', '視力改善取決於其他眼部損傷及弱視，不能只看水晶體是否復位。', '懸韌帶或遺傳問題仍在時，其他支撐、鏡片或眼壓可能再出問題。');
  d('d109', '依度數先配鏡，若嚴重影響視軸或不規則屈光，可評估水晶體手術；同時尋找相關全身病因。', '鏡片需隨變化調整；若手術，恢復多需數週，兒童弱視治療及全身追蹤可能更久。', '去除屈光障礙有機會改善，但視力仍受黃斑、視神經及早期弱視影響。', '先天構造不會被眼藥改變，之後仍需追蹤度數與水晶體狀態。');
  d('d110', '可選眼鏡、接觸鏡或合適的人工水晶體植入，依年齡、角膜及剩餘支撐決定。', '光學矯正宜及早進行，驗配或術後適應常需數週；兒童須隨成長調整並長期治療弱視。', '能恢復對焦不代表恢復原本調節力，合併眼病或弱視會限制最佳視力。', '度數、角膜耐受或鏡片位置可能變化，需持續維護與追蹤。');
  d('d111', '先確認眼表、鏡片及視網膜狀況，可選觀察適應、調整眼鏡或藥物；持續嚴重者再討論特定雷射或鏡片手術。', '部分在數週至數月適應而減輕；未改善時需重新評估，不能保證只要等就一定消失。', '不少症狀可改善，侵入性處理也有風險；術前需確認最可能的光學來源。', '改善後仍可能受瞳孔、照明或鏡片位置影響，新的症狀須排除其他眼病。');
  d('d112', '依偏位程度可觀察或配鏡，影響視力、引起發炎或高眼壓時，可選重新固定或更換人工水晶體。', '急性變化先檢查，手術後恢復通常以數週至數月計，度數需穩定後再配鏡。', '鏡片置中可改善部分重影與模糊；角膜、黃斑或外傷損害仍會限制結果。', '原支撐不足或固定材料變化可能再移位，需要長期追蹤。');
  d('d113', '先等待眼表與度數穩定，輕度誤差可用眼鏡或接觸鏡；合適者再選角膜屈光處置或鏡片相關手術。', '通常先在術後數週觀察穩定度，個別介入時機依病因，不宜太早反覆更改鏡片。', '多可改善剩餘度數，但最佳矯正視力若仍不好，要另找眼部病因。', '角膜或鏡片位置若繼續變化，度數可能再變；追加矯正前需評估長期穩定性。');

  d('d114 d115 d121 d355', '通常以處方抗發炎與散瞳止痛眼藥控制，反覆或有全身疾病時再評估免疫治療；先排除感染。', '一般急性發作常需數週治療並逐步減藥；較重或反覆型可能需數月，不能紅眼消退就立刻停藥。', '及早控制多有改善機會；後遺症可包括沾黏、白內障、黃斑水腫與高眼壓。', '部分病型容易再發，新的畏光、疼痛或模糊應及早回診，不自行沿用舊藥。');
  d('d116 d124 d125 d126 d143', '依侵犯位置與嚴重度，選眼藥、眼周或眼內治療、全身免疫調節藥及生物製劑；有全身疾病時需共同控制。', '初步壓制發炎可能數週，但維持與減藥常以數月到數年計，需監測藥物安全及眼底功能。', '目標是減少反覆損傷並保留視力；眼睛看起來不紅也可能仍有眼內發炎或黃斑水腫。', '屬可能反覆或持續活動的疾病；停藥時機需看長期穩定度，不能只看一次視力。');
  d('d119', '通常需要特定抗病毒藥，同時在醫師監測下控制眼內發炎與眼壓；藥物選擇取決於是哪一類病毒。', '常需數週至數月，有些需較長維持或預防療程；要依眼壓、發炎及必要檢驗調整。', '控制後可改善，但反覆發炎與高壓可能傷害角膜、虹膜及視神經。', '病毒再活化可能復發，單用抗發炎眼藥不能保證控制病因。');
  d('d120', '先控制發炎及眼壓，若水晶體碎片或蛋白仍持續刺激，可能需手術清除或處理病變水晶體。', '急性期需密集回診，移除刺激來源後恢復常需數週，嚴重發炎可能更久。', '清除病因後通常較能控制，既有角膜、黃斑或視神經損害仍影響結果。', '若仍有殘留碎片或其他病因，發炎可再出現；症狀重回時需找原因。');
  d('d122', '同時評估腎臟與眼內發炎，以局部或全身抗發炎治療控制，必要時加入免疫調節藥。', '通常需數月追蹤，眼部與腎臟改善的速度可能不同；少數反覆眼炎需更長療程。', '多可改善，但仍需監測腎功能、眼壓與白內障等問題。', '眼炎可能在腎功能改善後再發，因此不能只依腎臟症狀決定停診。');
  d('d123', '核對藥物與發炎出現的時間，與原治療團隊討論是否調整或替代藥，同時治療眼內發炎。', '部分在藥物調整後數週改善，長效藥或免疫治療相關反應可能持續數月；不能自行停止必要癌症或感染治療。', '視力可隨發炎改善，但嚴重黃斑或視神經受影響時恢復較有限。', '再暴露同類藥物可能復發，是否可再用須由雙方團隊衡量。');
  d('d127 d128 d370', '多需及早全身抗發炎與免疫調節治療，必要時加局部治療，以控制脈絡膜與雙眼的免疫反應。', '急性反應可能數日至數週改善，但通常需數月以上緩慢調整，部分需多年維持。', '早期充分控制較有利；反覆發炎可造成萎縮、白內障或青光眼，視力不一定完全恢復。', '可能再發，尤其減藥過快時；即使另一眼原本沒有受傷，也要注意新症狀。');
  d('d129', '依病灶位置、大小與免疫狀態，選觀察或抗寄生蟲治療；需要類固醇時也必須有適當抗感染配合。', '需治療的活動病灶常約 4–6 週以上，依眼底反應延長；免疫低下或反覆者可能需預防療程。', '發炎消退後通常留下眼底疤痕；靠近黃斑或視神經的疤痕可影響永久視力。', '潛伏病灶可在疤痕旁再活化，新的飛蚊或模糊應及早檢查。');
  d('d130', '以控制眼內發炎為主，是否加抗寄生蟲或手術需依活動性及牽引程度判斷。', '發炎控制常需數週至數月，有牽引、疤痕或剝離時，治療及追蹤會更久。', '結果取決於黃斑、視神經是否受累；清除活動性發炎不能保證消除既有牽引。', '發炎可再次活動，也可能有延遲牽引併發症，需持續眼底檢查。');
  d('d131', '由眼科與感染科共同確認並使用完整抗結核療程，依眼部發炎需要加入適當抗發炎藥。', '抗結核通常至少約 6 個月，嚴重或改善慢時可能需 9–12 個月；必須依個人療程，不自行停藥。', '可控制感染與發炎，但既有眼底疤痕或缺血未必恢復；也需監測抗結核藥的眼部與全身副作用。', '療程不足、抗藥性或再次感染可能造成問題；眼炎再起仍要重新評估病因。');
  d('d132', '眼梅毒通常需依神經梅毒原則給靜脈青黴素，眼藥僅是輔助；同時安排其他感染及伴侶相關評估。', '主要靜脈抗生素療程通常為 10–14 天；視力與眼內發炎改善可能需數週以上，血液追蹤則持續數月。', '及早治療較可能保留視力，已造成視神經或黃斑損害時可能留後遺症。', '可再感染；症狀再發或血液數值變化需評估，不能只靠過去完成治療就排除。');
  d('d133', '有合適暴露背景並確認病因後，由感染科選擇全身抗生素，眼內發炎另作處理。', '抗生素常以數週計，依是否合併神經或其他器官病變調整；眼部恢復可能更慢。', '早期治療較有利，長期視神經或視網膜損害可能無法完全逆轉。', '再次蜱蟲暴露可再感染；症狀持續不一定代表仍需延長抗生素，需重新判斷。');
  d('d134 d135', '需立即全身抗病毒並可能合併眼內注射，同時處理免疫低下；若出現剝離可能需手術。', '急性密集治療後常需數月口服或維持治療，依病原及免疫狀態決定，眼底早期需密切追蹤。', '即使感染停止，壞死的視網膜也不會正常長回；有剝離及嚴重視力受損風險。', '可有延遲剝離、感染再活化或另一眼受累，不能只在紅痛時回診。');
  d('d136 d137', '依確切病灶選抗病毒或其他抗感染治療，並與感染科改善全身免疫狀態；必要時眼內注射。', '誘導治療常需數週，之後是否維持數月或更久取決於病原控制及免疫恢復，不能只靠視力好轉停藥。', '能阻止部分病灶繼續擴大，但感染已破壞的視網膜會留下疤痕，也可能合併剝離或免疫恢復發炎。', '免疫低下或停維持療程後可能再活化，需依感染科與眼科共同追蹤。');
  d('d138 d139 d369', '需緊急以眼內及全身合適抗感染藥控制，部分需玻璃體手術；同時清除血流、外傷或其他感染源。', '急性期按小時到數日密集評估，藥物與後續恢復常需數週至數月，黴菌或全身感染可更久。', '屬嚴重視力急症，結果取決於病原、病灶位置與治療時機，不能保證恢復原視力。', '感染源未清除、免疫低下或殘留異物可能再發；新痛或視力下降需立即回診。');
  d('d140', '確認診斷後多可先觀察，必要時依嚴重度處理發炎；須排除需要抗感染或其他治療的相似疾病。', '常在數週至約數月內逐步改善，視野或光感不適可能比視力表恢復慢。', '多數有良好恢復機會，少數仍留小範圍視覺改變。', '多為單次病程，但仍可能再發或出現其他病型，持續惡化時要重新檢查。');
  d('d141', '依眼底與神經症狀選觀察或抗發炎治療，有中樞神經血管炎疑慮時需緊急跨科處理。', '眼底病灶常需數週至數月演變；神經受累者療程通常更長，不能只按眼睛恢復決定。', '多數眼部病灶可改善，但黃斑受損或全身血管炎會影響預後。', '可有新病灶或神經併發症，新的劇烈頭痛或神經症狀需立即就醫。');
  d('d142 d144 d145', '先區分感染與免疫性病因，再選抗感染或免疫調節；若合併新生血管，可能另外需要眼內注射。', '常需數週至數月控制，反覆型可能長期維持；影像及視野的變化比外觀紅不紅更重要。', '治療以減少新的視網膜傷害為主，既有萎縮或疤痕不一定逆轉。', '可能再活躍，新變形、暗點或視野改變應提早檢查。');
  d('d146 d233', '取得適合檢體確認後，由眼科與血液腫瘤團隊選眼內藥物、全身化療或其他療法，並評估中樞神經。', '治療多需多次或多個療程，常以數月計；結束後仍需多年監測眼內與神經系統。', '眼部病灶可改善，但控制眼睛不等於排除其他部位病變，整體預後與分期及反應有關。', '可在眼內或中樞神經復發，短暫對類固醇有反應不代表已治好。');
  d('d147 d148 d149', '以控制血糖、血壓與血脂及定期眼底檢查為主；較重或有黃斑、增殖性變化時再選雷射或注射。', '需要長期管理，眼底穩定通常以月與年追蹤，無法靠短期點眼藥清除所有病變。', '及早追蹤能在影響視力前發現可治療變化；看得清楚不代表血管病已消失。', '糖尿病仍存在時可能進展，治療或血糖改善後仍要定期散瞳檢查。');
  d('d150', '可選周邊視網膜雷射或規律抗血管新生注射；大量出血、牽引或剝離時可能需玻璃體手術。', '雷射可能分次完成，注射常需持續數月以上；手術後恢復需數週到數月，之後仍長期監測。', '可降低嚴重出血及剝離風險，但黃斑缺血或既有損傷可能使視力無法完全恢復。', '新生血管與出血可再發，尤其注射中斷或缺血未控制時，不能自行停診。');
  d('d151 d153 d154 d155', '依黃斑是否受累與視力選觀察、抗血管新生注射、類固醇或適合的雷射；並處理全身血管風險。', '需要注射者常先約每月評估及治療，之後依影像拉長間隔；可能持續數月到數年，不是打一次就結束。', '水腫消退可能改善視力，但缺血、長期積液及疤痕會限制恢復；部分良好視力者可先密切觀察。', '水腫與新生血管可能再出現，即使視力暫時穩定也要依約檢查。');
  d('d152', '主要控制全身危險因子並追蹤；若同時有水腫可另外治療，但不能把消水腫視為已恢復供血。', '通常需長期追蹤，沒有一段固定眼藥療程可保證把缺血區恢復正常。', '視力取決於黃斑缺血範圍，治療其他併發症後仍可能受限；可用低視能方式協助生活。', '全身與視網膜血管問題可能持續變化，需留意新水腫或其他血管併發症。');
  d('d156 d157', '立刻到有中風處理能力的急診，評估栓塞來源與時間敏感的處置；後續以預防再中風及控制血管風險為重點。', '急性評估按分鐘與小時計，不能先在家等待；之後血管檢查與預防是長期計畫，視力變化可能在數週內觀察。', '視網膜缺血可造成永久視野或視力損失，目前沒有保證恢復的治療；必要時安排視覺復健。', '可能再有眼部或腦部血管事件，因此即使眼睛無法恢復，找病因與預防仍很重要。');
  d('d158', '需評估頸動脈與全身血管，依病因選血管、內科或其他治療；眼部新生血管、高眼壓及疼痛也要同步處理。', '急性變化需立即處理，血管風險與眼部監測通常長期進行；不是單靠短期眼藥。', '改善供血與併發症可保護剩餘功能，但長期缺血造成的損傷不一定恢復。', '血管狹窄或危險因子仍在時可繼續惡化或再發，需多專科追蹤。');
  d('d159 d166', '以處理高血壓、血液或代謝原病為主，眼部水腫、出血或缺血併發症再另行治療。', '急症需即刻全身處理；眼底出血或水腫可能數週至數月消退，原疾病通常需更長期管理。', '可逆性滲漏可改善，嚴重缺血或視神經受損時可能留下視力影響。', '原疾病失控時眼底變化可能再出現，因此眼症狀消退後仍需全身追蹤。');
  d('d160 d165', '依出血與滲漏位置選觀察、注射、雷射或手術，並評估血壓、外傷與相關全身病因。', '積血可能需數週至數月吸收；若黃斑下大量出血，介入時機可能較急，不能全部等自然吸收。', '預後取決於出血在哪一層及黃斑是否受損，部分可明顯改善，缺血或疤痕則可能持續。', '血管或誘因未控制可能再次出血，新變形或突然視力下降需及早檢查。');
  d('d161 d220', '較輕可依滲漏程度觀察或用雷射、冷凍控制異常血管；嚴重積液或剝離可能需手術及其他輔助。', '常要分次治療，脂質與積液改善以數月計；兒童還需長期追蹤弱視。', '越早控制且黃斑未嚴重受損越有利；晚期剝離可能主要以保留眼球為目標。', '異常血管與滲漏可能再活躍，完成一次雷射後仍需長期檢查。');
  d('d162 d163', '依血管炎、缺血及新生血管選病因治療、雷射或注射，反覆積血或牽引剝離可能需手術。', '活動期可能需數週至數月治療，缺血及全身病需長期照護；積血吸收速度因人而異。', '處理新生血管能降低部分出血風險，既有缺血及牽引仍會限制視力。', '可再出血或長出新血管，因此平時無症狀也需定期眼底檢查。');
  d('d164', '可用注射等方法控制部分黃斑水腫與新生血管，並追蹤視神經及眼壓；治療依原放射範圍選擇。', '可能在放射後數月甚至數年才出現，注射與監測常需長期進行。', '可以減輕部分滲漏，但放射造成的缺血或視神經損害未必能逆轉。', '屬可能延遲進展的病變，治療後仍可能再次水腫或視力下降。');
  d('d167', '以戒菸、生活與飲食調整、定期影像監測為主；符合中期或特定單眼晚期條件者可討論 AREDS2 補充，不是一律注射。', '通常長期按月到年追蹤，沒有短期療程能清除所有玻璃疣；每日自我監測需持續。', '不少患者可多年保持實用視力，但仍可能進展到萎縮或新生血管，不能只依目前清楚度判定。', '屬慢性變化，重點是偵測進展；新直線變彎或暗點需及早就醫。');
  d('d168', '以視覺輔助與監測為基礎；部分地區可評估補體抑制劑注射以減緩萎縮擴大，需比較風險、負擔與實際可近性。', '若選注射，通常為長期重複治療，依產品及反應排程；沒有短期注射能把萎縮組織長回。', '目標是減慢結構惡化，不能保證改善現有視力；閱讀輔具與照明仍很有幫助。', '萎縮通常持續存在或進展，並需監測濕性轉變與注射相關發炎。');
  d('d169 d171 d172', '以抗血管新生注射控制滲漏，部分息肉型病灶可再討論光動力治療；治療方式依眼底影像決定。', '常先約每月評估，之後依反應延長或調整間隔，許多患者需數年追蹤與重複治療。', '及早治療較能保留中央視力；已有疤痕、萎縮或長期出血時改善有限。', '很可能再滲漏或出血，眼底乾燥後也不能自行中斷回診。');
  d('d170', '儘速評估出血大小與時間，可選抗血管新生注射、氣體移血、溶血輔助或玻璃體手術，並處理出血來源。', '初期決策需及早進行，積血吸收與視力恢復以數週至數月計，後續注射可能更久。', '結果取決於黃斑受血壓迫的時間及原疾病，移血成功不等於感光細胞完全恢復。', '原新生血管仍可能再出血，需持續影像與病因治療。');
  d('d173', '部分急性病例可先觀察並調整誘因；持續、反覆或影響特殊用眼需求時，再評估光動力或適合的雷射。', '積液常在數週至約 3–4 個月內改善，但未改善、反覆或視力惡化時需提早討論治療。', '首次短病程多有較好恢復，仍可能殘留輕微變形或對比下降；長期積液會增加損傷。', '可能復發，需告知所有類固醇來源；調整全身藥須與原開藥醫師討論。');
  d('d174', '持續積液可評估調整參數的光動力等治療，並檢查是否合併新生血管；非每例都適合一般眼內注射。', '治療後積液改善通常以數週至數月評估，之後仍需長期監測。', '可以控制部分積液，但長期色素上皮與感光細胞損傷可能使視力無法完全恢復。', '可再積液或出現新生血管，新變形或視力變差應提早檢查。');
  d('d175', '依手術後或其他病因選抗發炎眼藥、眼周／眼內治療；需先區分糖尿病、靜脈阻塞與感染。', '常以數週至數月評估消腫，反覆或慢性病例可能需要較長療程。', '不少可隨水腫消退改善，但長期積液或其他黃斑損傷可能留下視力影響。', '減藥後或再次發炎可復發，症狀改善後仍應按影像調整治療。');
  d('d176 d178 d179', '輕微且穩定者可觀察；持續變形、牽引或視力下降時，可評估玻璃體手術及剝膜，不是每個影像異常都需手術。', '觀察以月追蹤，術後初期恢復約數週，黃斑功能改善常需數月。', '可減少牽引與部分變形，已形成的感光細胞損傷不一定完全逆轉。', '可能進展、新生裂孔或再形成膜；出現新中心暗點需回診。');
  d('d177 d366', '依裂孔大小、成因與時間選短期觀察或玻璃體手術，手術可能合併內界膜處理及氣體；外傷型部分可自行閉合。', '手術初期需數週照護，視力可能數月改善；姿勢與氣泡時間依實際手術決定。', '裂孔閉合與視力恢復不同，較久或較大裂孔可能殘留中央功能限制。', '少數可能未閉合或再開，需要追加手術；氣泡未完全吸收前須遵守飛行與麻醉限制。');
  d('d180 d186', '依是否為萎縮、牽引、裂孔或新生血管選觀察、特殊鏡片、注射或手術，不能只用增加眼鏡度數處理。', '結構穩定者長期追蹤；注射或手術反應常以數週至數月評估。', '可處理部分併發症，但高度近視造成的萎縮及眼球形狀不會因治療完全消失。', '可能出現新的牽引或新生血管，需持續監測變形、暗點及視野變化。');
  d('d181 d182', '若有活動新生血管，常以抗血管新生注射控制；沒有活動滲漏時依影像追蹤，並處理相關全身風險。', '常先治療後約一個月檢查，再依活動性追加；有些需較少次數，有些會反覆，不能預先保證總針數。', '早期控制可保留較多中央視力，既有黃斑疤痕或萎縮仍影響最終結果。', '新生血管可能再活化，原來的近視或膜層脆弱也仍存在。');
  d('d183 d256', '沒有黃斑積液可觀察；積液或劈裂影響視力時，可評估玻璃體手術等方式減少液體與牽引。', '通常以月追蹤，手術後積液可能需數月才慢慢吸收。', '及早處理持續病變較有利，但長期黃斑損傷可能限制恢復。', '液體可能持續或再出現，需要依影像決定是否追加治療。');
  d('d184', '先停止日光或雷射暴露並檢查黃斑；多以觀察及視覺支持為主，沒有已證實能保證修復所有損傷的眼藥。', '部分症狀在數週至數月改善，殘留暗點可能更久。', '輕微傷害可改善，較深感光細胞受損可能留下永久中央暗點。', '避免再次暴露才能預防新損傷，普通太陽眼鏡不能安全用來直接看太陽。');
  d('d185', '找出傷口滲漏、過度引流或其他低眼壓原因，依情況調藥、修補或手術，以恢復適當眼壓。', '原因處理後皺褶與視力可在數週至數月改善，長期低壓的恢復可能較慢。', '及早恢復眼球形態較有利，長期皺褶或黃斑損傷可能留下視覺影響。', '引流或傷口問題仍在時可再低壓，需要持續追蹤眼壓與黃斑。');
  d('d187', '先散瞳排除裂孔；沒有裂孔時通常不需藥物或雷射，依風險安排複查。', '閃光與飛蚊常在數週至數月較不明顯，但部分飛蚊可能持續存在。', '單純後玻璃體剝離多不傷害中央視力；重點是及時發現可能伴隨的裂孔或出血。', '同一段分離過程可能後來才拉出裂孔，另一眼也可能日後發生；新黑幕或飛蚊大增立即就醫。');
  d('d188', '有症狀或高風險裂孔可選雷射或冷凍形成黏著；低風險病灶可觀察，已剝離者可能需手術。', '處置多為門診完成，黏著形成及早期觀察約需一至數週；之後依風險複查。', '目標是降低剝離風險，並不是消除所有飛蚊；已存在的黃斑問題需另處理。', '原處或其他位置仍可能出現裂孔與剝離，治療後黑幕、閃光或飛蚊暴增不能忽略。');
  d('d189 d193', '多數穩定、無症狀者可觀察；有特定裂孔、進展或其他高風險條件才評估雷射或手術。', '通常需長期定期檢查，並沒有所有人都需完成的短期療程。', '不少可多年保持穩定，不代表一看到退化或劈裂就一定會失明。', '原本構造持續存在，少數可進展或合併裂孔；新的閃光、飛蚊或黑幕需急查。');
  d('d190 d191 d194', '依裂孔、牽引與疤痕選玻璃體切除、鞏膜扣壓、氣體或矽油等方式，部分需合併雷射並分次手術。', '傷口與不適常需約 2–6 週改善，視力恢復通常需數月；複雜剝離或矽油移除會延長整體療程。', '復位可保護眼球與剩餘功能，視力取決於黃斑是否受累、剝離多久及是否缺血，不能保證完全恢復。', '可能因新裂孔或疤痕再次剝離，需要追加手術；術後仍須監測新黑幕。');
  d('d192 d195 d237', '先找出發炎、腫瘤、低眼壓或眼球壁等原因，再選病因治療、觀察、引流或其他手術。', '積液吸收常以數週至數月計，出血或持續病因可能更久；急性劇痛與視力驟降需即刻處理。', '及早控制原因可能讓視網膜或脈絡膜復位，長期黃斑受影響者視力可能不完全恢復。', '原病因再活躍或眼壓異常時可能再積液，需要持續追蹤。');
  d('d196 d197', '先排除裂孔與剝離，再治療出血來源；可選觀察吸收、雷射／注射或玻璃體手術。', '積血可能數週至數月吸收，濃厚或不吸收者需再評估手術；眼底看不清時仍需影像與複診。', '血清掉後能看多清楚，取決於視網膜與視神經原本狀態，不只取決於積血多少。', '新生血管、裂孔或全身原因未處理可再出血；突然新黑幕須立即檢查。');
  d('d198', '多數只需觀察；若確實嚴重影響視覺功能，才在排除其他原因後討論玻璃體手術風險。', '沉積常長期存在，沒有短期眼藥可溶解；是否介入依實際困擾決定。', '多數不會因沉積本身嚴重失明，視力下降仍需找白內障或眼底原因。', '屬持續存在的玻璃體變化，新的飛蚊或閃光不能一律當成原來沉積。');

  d('d199-d204 d207 d214', '以屈光矯正、濾光、低視能與行動支持維持功能，並處理白內障、水腫等併發症；依確定基因或代謝病因評估特定療法及試驗。', '多數需長期甚至終生照護，沒有固定幾週就能治癒的療程；功能、影像與家族評估以月或年持續追蹤。', '病程因基因與個人而不同，治療可改善生活與部分併發症，但不能保證讓退化的感光細胞重生。', '多屬持續存在或逐漸變化的疾病，不是一次治療後的普通復發；突然惡化仍需排除可治療併發症。');
  d('d205 d206 d376', '依活動性追蹤黃斑，出現新生血管時可選抗血管新生注射；沒有活動滲漏時以監測與視覺支持為主。', '通常長期追蹤；有新生血管時先按月評估注射反應，再調整間隔，療程因復發而可能延長。', '可控制部分滲漏並維持實用視力，但基因相關沉積或萎縮不一定停止。', '病因仍存在，新生血管或滲漏可能再發；新變形或中央暗點要提早回診。');
  d('d208', '由代謝專科規劃適當飲食與營養監測，評估是否對維生素 B6 等治療有反應，並處理屈光與其他併發症。', '代謝控制通常需長期持續，視功能以月到年追蹤，不能短期自行限食或補充後就停止。', '及早控制可能減少後續損傷，但已萎縮的視網膜與脈絡膜通常不會恢復。', '代謝問題會持續存在，停治療或營養不當可能再影響控制。');
  d('d209 d210 d211', '以正確屈光矯正、濾光、環境照明及學習支持為主，依電生理與基因型確認是否有可處理的併發症。', '多屬長期功能照護，沒有一段常規眼藥療程能把先天訊號功能改為正常；成長期需調整鏡片與支持。', '部分病型相對穩定，但視力、夜視與畏光限制可能持續；少數變異會進展，需依個人檢查判斷。', '不是典型感染後復發；新的視力變化仍需重新檢查，不能一律歸因於先天病。');
  d('d212', '以影像與視功能追蹤為主，部分黃斑積液可試適合藥物；合併出血或剝離時再評估手術。', '用藥效果常需數週至數月評估，長期追蹤則持續多年；不是所有劈裂都需要開刀。', '中央視力受結構及病程影響，手術或消腫不一定讓視網膜恢復正常。', '可有再次積液、出血或剝離，避免碰撞並留意新症狀。');
  d('d213 d218', '依周邊血管、裂孔或牽引風險選觀察、預防性處置、雷射或手術，並評估家族及全身病型。', '通常需終生或長期追蹤，介入後傷口需數週修復，兒童另需視覺發展照護。', '及早發現危險變化可保留更多功能，已發生的剝離、萎縮或弱視會限制結果。', '遺傳結構或血管問題仍在，可能有新的裂孔、滲漏或剝離，家人也可能需檢查。');
  d('d215 d216 d249', '確認可疑毒性後，與原開藥醫師共同評估停藥、減量或替代治療；不要自行停用必要藥物。', '篩檢需依風險長期進行；調藥後視功能變化可能數週至數月，部分毒性即使停藥後仍可進展。', '及早發現較能減少損傷，但藥物造成的視網膜或視神經傷害可能不可逆。', '再次使用相關藥可能再受影響；已受損者即使停藥也可能需要後續監測。');
  d('d217 d308', '依分期與位置選嚴密觀察、雷射或抗血管新生注射；進展至特定剝離時可能需手術。', '初期可能每數天至數週檢查，治療後仍追蹤數月以上；注射後再活化可能較晚，出院不代表篩檢完成。', '及時處理可降低嚴重剝離風險，最終視力也受早產相關神經與屈光問題影響。', '可能再活化或出現近視、斜視、弱視，仍需長期兒童眼科照護。');
  d('d219', '依是否阻擋視軸、牽引及眼球發育程度選觀察或手術，並安排配鏡及弱視治療。', '手術恢復需數週至數月，視覺發展與眼壓追蹤通常持續多年。', '視力潛能因先天構造差異而不同；移除混濁或牽引不一定達到正常視力。', '原發育異常仍可能伴眼壓、牽引或視軸問題，需要後續追蹤。');
  d('d221 d375', '先緊急處理全身與腦部傷勢，眼科確認出血及視網膜狀況；同步安排兒童安全、復健與家庭支持。', '急性評估需立即進行，出血可能數週至數月吸收，神經與視覺復健可能更久。', '視力不只取決於眼底出血，也受腦部、視神經及其他傷害影響，需要分階段評估。', '重點是預防再次受傷並維持安全照護；外觀恢復不代表不需後續追蹤。');
  d('d222 d227 d229 d230 d231 d232', '先確認病灶類型，多數穩定良性病灶可觀察；有生長、滲漏或影響黃斑時，才選雷射、注射或其他適合處置。', '通常以月到年比較影像，沒有每例都需要的短療程；處置後吸收與功能恢復可能需數週至數月。', '良性不等於一定不影響視力，結果取決於病灶位置與是否有出血、牽引或新生血管。', '病灶可能持續存在或出現新併發症；有特定全身關聯時也需跨科追蹤。');
  d('d223 d224', '由眼腫瘤團隊依大小與位置選局部放射線、特定切除或眼球摘除；同時評估轉移風險與全身監測。', '局部治療可能分數日或特定次數完成，腫瘤反應與眼部恢復常需數月；全身與眼部追蹤通常持續多年。', '控制腫瘤與保留視力是不同目標，放射或原病仍可能傷害黃斑與視神經，且需留意全身風險。', '可局部復發或之後轉移，眼內病灶縮小後仍需按分期長期追蹤。');
  d('d225 d343', '需與原癌症團隊分期，依腫瘤種類選全身藥物、眼部放射或其他局部處理，以保護視力與減少症狀。', '治療常以數週至數月的療程評估，後續依全身癌症反應持續調整。', '眼部症狀可能隨腫瘤控制改善，整體預後主要與原癌症及轉移範圍有關。', '可再出現眼部或其他部位病灶，需與全身腫瘤追蹤同步。');
  d('d226', '無症狀可觀察，影響黃斑的滲漏可評估光動力、放射或其他專科治療。', '治療可一次或分次完成，積液與視力變化通常在數週至數月追蹤。', '控制滲漏有機會改善視力，長期積液造成的黃斑損傷可能無法完全恢復。', '病灶或滲漏可再次活動，穩定後仍需定期影像。');
  d('d228', '治療依分期選全身、眼動脈或特定眼內化療，配合雷射、冷凍；無法安全保眼時可能需摘除，並安排遺傳評估。', '多需數月、多個療程及反覆麻醉檢查；治療後仍要多年監測另一眼、復發及其他腫瘤風險。', '首要是保命，再評估保眼與視力；保留眼球不一定代表有正常視覺。', '可有新病灶、復發或相關第二腫瘤，家族與孩子的長期追蹤都很重要。');
  d('d234 d235 d331 d332', '依病理深度與範圍，選邊界控制切除、局部藥物、冷凍或放射；部分需地圖式活檢、淋巴結或全身分期。', '切除後傷口通常需數週，局部藥物可能分週期用數週至數月；腫瘤追蹤通常持續多年。', '早期、局限且完整控制者較有利；視力及外觀也受切除範圍、眼表與重建影響。', '可局部復發，部分病型可轉移；不因表面看不到病灶就停止追蹤。');
  d('d236 d339', '先以病理確定類型並全身分期，再選局部放射、免疫或全身治療；不是所有病灶都靠手術切光。', '治療常以數週至數月計，之後需長期檢查眼部與其他器官。', '部分局限型控制良好，但預後因淋巴瘤種類與分期差異很大。', '可能在原處或其他部位再出現，治療後仍需血液腫瘤與眼科追蹤。');
  d('d238', '眼科與腫瘤團隊共同找出並治療原癌症，依情況評估免疫調節及低視能支持。', '常需數月以上評估反應，全身腫瘤治療與視覺支持可能長期持續。', '治療目標是盡量保存功能，已受損的感光細胞可能無法恢復，反應因病型而異。', '原癌症或免疫反應仍在時，視功能可能繼續變化，需要長期整合追蹤。');
  d('d239', '先以影像與神經評估確認類型，部分可觀察，部分使用類固醇加速恢復，並評估相關脫髓鞘疾病。', '典型病例常數週開始改善，恢復可延續數月；神經風險評估與必要治療可能更久。', '不少可恢復良好視力，但色覺、對比或疲勞時視覺可能未完全正常；非典型病因預後不同。', '可能再發或之後有其他神經症狀，需依病因安排追蹤。');
  d('d240 d241', '急性發作需及早神經免疫治療，可能用高劑量類固醇、血漿置換等方式；再依病型選復發預防藥。', '急性治療按日到週處理，恢復可能數月，長期預防常需數年並監測安全。', '不同抗體病型的恢復差異很大，嚴重發作可留下永久損害，不能套用一般視神經炎的預期。', '有再發風險，預防用藥不能只因視力暫時改善就自行停用。');
  d('d242 d244', '先排除需要立即治療的血管炎或壓迫，並處理血壓、貧血、睡眠呼吸中止等風險，必要時視覺復健。', '急性病因先處理，視力及視野通常在數週至數月觀察穩定，血管危險因子需長期控制。', '缺血損傷常無法完全逆轉，目前沒有可保證恢復的常規治療。', '另一眼或其他血管事件仍有風險，須持續全身照護，勿自行改降壓藥。');
  d('d243', '高度懷疑時立即全身類固醇，不能等切片結果；依病況加免疫調節藥並保護骨骼等，目標也包括保護另一眼。', '急性治療立即開始，整體療程常需約 1–2 年或更久，減藥速度依症狀及檢驗決定。', '已有的嚴重視力損失常難恢復，因此及早阻止另一眼受累非常重要。', '減藥期間或之後可再活躍，新的頭痛、咀嚼痛或視覺症狀須立即聯絡醫療團隊。');
  d('d245', '排除其他顱內病因後，依視力風險選體重管理、藥物，必要時採保護視神經或降低顱壓的手術。', '常需數月到數年控制，視野威脅時處理需更急；追蹤頻率看視神經與視野而非只看頭痛。', '及早降壓可保護視力，長期視神經受壓可能造成永久視野損失。', '體重或原風險改變時可能再發，頭痛消失也不等於視神經已安全。');
  d('d246 d247 d278', '依病灶性質、生長、視功能與內分泌狀況選觀察、放射、藥物或手術，由相關神經與腫瘤團隊共同決定。', '觀察可能持續多年，治療常以數週到數月計；解除壓迫後功能仍可能需數月才穩定。', '預後取決於壓迫多久、視神經是否萎縮及病灶位置；移除或控制腫瘤不保證視力完全恢復。', '病灶可能再長或需追加治療，仍需影像、視野與全身追蹤。');
  d('d248 d374', '先排除眼窩高壓等可立即處理的原因；間接性視神經傷害需個別討論觀察與支持，常規超高劑量類固醇或減壓未證實普遍有效。', '急症先按分鐘處理，非可逆傷害的視功能可能需數週至數月觀察，復健與心理支持可更久。', '部分可有自然改善，但嚴重視神經損傷可能永久存在，不能保證用藥或手術可恢復。', '不是典型復發病，重點是避免再外傷並追蹤共同的眼部與腦部損傷。');
  d('d250', '立即急診接受解毒、代謝與可能透析處理，不是先等眼藥治療；同時處理全身酸中毒。', '急救按小時進行，之後住院及視功能追蹤可能數週到數月。', '可能危及生命與造成永久視神經損害，治療越早越有利但無法保證恢復。', '避免再次暴露不明酒品或溶劑，視力穩定後仍可能需要復健。');
  d('d251', '確認缺乏的營養與吸收原因後適當補充，並改善飲食、酒精或其他相關因素，不是只加一般保健品。', '通常需數週至數月觀察功能恢復，若吸收不良或其他病因持續，補充與監測需長期進行。', '及早補足有較好恢復機會，已明顯視神經萎縮者可能殘留視覺限制。', '缺乏或吸收問題未解決時可再出現，需要持續營養與全身追蹤。');
  d('d252 d253', '安排分子診斷與遺傳諮詢，依病型及時間評估適用藥物或試驗，同時提供低視能支持並避免菸與大量酒精。', '通常是長期照護，若用特定藥需以數月以上評估，沒有固定短療程可保證恢復。', '恢復與進展因基因及個人差異很大；視覺輔具可改善生活，但已萎縮的視神經未必恢復。', '基因差異持續存在，需監測另一眼、功能與可能全身表現，並非感染清除後的復發。');
  d('d254 d258', '先確認是先天構造或沉積而非真正顱內壓升高，再依視野與影像追蹤；合併青光眼等問題才另外治療。', '通常長期定期比較，沒有常規眼藥能去除所有構造變化。', '不少患者保持穩定視力，但部分可有視野缺損或其他併發症。', '不是一般的復發性發炎；任何新的視力、頭痛或神經症狀仍需重新判斷。');
  d('d255 d257', '以配鏡、弱視及功能支持為主，依病型安排內分泌、腦部或全身評估；出現剝離等併發症時另行處理。', '眼球先天構造無法用短期療程改變，視覺發展與全身追蹤常持續整個成長期。', '視力潛能取決於神經與黃斑發育；輔具與適當環境可幫助使用剩餘視覺。', '先天差異通常持續存在，需留意後續眼底或全身問題，而不是等待它自行長好。');
  d('d259', '重點是找到交感神經路徑的病因，依檢查結果治療；新發頭頸痛者須先排除血管急症。', '急性病因需立即評估，之後恢復時間取決於神經受損原因，可能需數週至數月或持續存在。', '瞳孔與下垂不一定完全恢復；整體預後更取決於背後血管、腫瘤或其他病因。', '新症狀或變化需重新檢查，不能只因以前診斷過就忽略。');
  d('d260', '確認是強直性瞳孔後，無困擾可觀察；畏光或近距離不適可用鏡片或選定處方眼藥協助。', '對焦與瞳孔反應可在數月以上逐漸改變，有些差異會長期存在。', '多數不會因瞳孔本身失明，但近用與光線適應可能需調整。', '瞳孔狀態可隨時間變化，另一眼也可能受影響；新的下垂、複視或頭痛需另外評估。');
  d('d261', '需找出神經梅毒等根本病因並接受相應全身治療，不能只靠縮瞳或散瞳眼藥。', '療程依確定病因安排，抗感染可能需特定完整療程，瞳孔改變不一定很快消失。', '處理病因可減少後續損害，但既有神經反應異常可能持續。', '後續追蹤以原疾病控制為主，不能只看瞳孔大小判斷是否治好。');
  d('d262', '先核對藥物與接觸物，確認沒有神經或高眼壓急症後，通常停止不必要暴露並觀察。', '可能數小時至數日逐漸恢復，長效藥可更久；超出預期或有新症狀須再檢查。', '單純藥效多可消退，期間可暫時畏光或看近模糊。', '再次接觸相同藥物可能再散瞳，應避免交叉污染並保留藥名。');
  d('d263', '這是檢查徵象，治療需針對造成不對稱的視神經或視網膜病因，而非直接把瞳孔反應改回來。', '急性視力變化要立即處理，後續療程依真正病因，可能短期也可能長期。', '預後由原疾病與神經損害程度決定，不能單靠這項徵象預測恢復。', '若原病進展或另一眼受累，反應也會改變，需追蹤視功能。');
  d('d264 d265 d266', '先釐清血管、壓迫、外傷或其他神經病因，再治療原病；可用遮蓋或稜鏡暫緩複視，穩定後才討論斜視手術。', '急症必須先排除，部分微血管型可在約 3–6 個月改善；其他原因時間不同，不能一開始就只等待。', '有些可恢復良好眼球運動，有些仍留偏斜或複視，之後可再用光學或手術協助。', '原血管或神經病可能再發，新的瞳孔變化、下垂、頭痛或神經症狀需立即評估。');
  d('d267 d268 d269', '需以影像與神經評估找出腦幹、海綿竇、眼窩尖或其他病灶，依感染、血管或腫瘤原因治療。', '急性發作先緊急處理，恢復可能數週至數月，腫瘤或慢性免疫病療程可能更久。', '取決於原病與是否傷及視神經，複視改善與視力恢復不一定同步。', '原病可再活動或進展，需按專科計畫追蹤，不只處理眼位。');
  d('d270 d272 d273', '以神經與全身病照護為主，眼部可用潤滑、配鏡、稜鏡或選定下垂／眼位處置，並注意心臟、吞嚥及復健需求。', '多需長期照護，眼部介入恢復可能數週，但不會結束原本神經或肌肉病程。', '治療旨在改善舒適、頭位與生活功能，不能保證恢復完全正常眼球運動。', '可能隨原病持續變化，術後眼位或下垂也可能再改變，需要重新調整。');
  d('d271', '神經科依病況選改善神經肌肉傳遞或免疫治療，暫時可用遮蓋等方式緩解複視；手術僅限特定穩定情況。', '部分症狀可較快改善，免疫治療常需數週至數月，維持及全身監測可能長期進行。', '眼部波動可控制，但疲勞時仍可能變化；須留意是否影響全身肌肉。', '感染、藥物或原病活動可再加重；吞嚥、說話或呼吸困難須立即急診。');
  d('d274 d333 d334', '先戒菸、維持甲狀腺穩定與保護眼表；活動性中重症可選免疫治療，穩定後再依需求分階段做減壓、斜視或眼瞼手術。', '活動與穩定過程常以月到年計；藥物可能數週至數月，重建手術也常需分期，視神經受壓則需急處理。', '發炎與突出可改善，但纖維化、複視或眼瞼改變可能殘留；甲狀腺數值正常不等於眼病立即消失。', '可能再活躍或有殘留症狀，吸菸會增加風險；視力或色覺下降需立即回診。');
  d('d275 d277', '先檢查視網膜、視神經與屈光，配鏡並治療弱視；明顯異常頭位可評估特定手術，需另排除警訊。', '多需隨成長長期追蹤，鏡片適應或手術恢復以週計，視覺發展需更久。', '可改善功能與頭位，但不能保證眼震完全消失，視力取決於背後視覺病因。', '眼震或頭位可能隨疲勞、視力及成長改變，後續仍可能需調整。');
  d('d276', '先找出神經、前庭或藥物因素，依病因治療，部分可用處方藥或視覺策略減少影像晃動。', '原因可逆者可能數週至數月改善，慢性神經病可能需長期症狀控制。', '改善程度因病因差異很大，症狀減輕不一定代表神經病因完全消失。', '原病或用藥變化可再出現，新發頭痛、不穩或其他神經症狀需重新評估。');
  d('d279 d280', '處理腦部病因，並用視覺復健、掃視訓練、閱讀與環境調整提高功能；兒童需結合學習支持。', '復健常以數週至數月起步，適應與發展可持續更久；急性中風先依急救流程處理。', '部分可適應或改善，受損視野不一定完全恢復；生活功能可透過訓練與輔具提升。', '是否再惡化取決於原病，還需防跌、行動與駕駛安全評估。');
  d('d281', '確認是典型偏頭痛後，可調整誘因、生活與急性止痛，發作頻繁時討論預防藥；首次或非典型視覺症狀先排除血管急症。', '典型先兆常在數十分鐘內消退，頭痛可較久；預防治療常要數週至數月評估並持續一段時間。', '典型先兆通常可恢復，但持續或真正單眼黑矇不能直接當成偏頭痛。', '可能反覆，睡眠、壓力及荷爾蒙等會影響；新的發作型態需再評估。');
  d('d282', '以清楚說明診斷、支持性照護及適當功能復健為主，也要處理可能並存的眼病、神經或心理壓力。', '改善可能數週至數月，速度因人不同，需建立可追蹤的功能目標。', '有改善機會，症狀是真實困擾；不能用責備或反覆無目的檢查取代支持。', '壓力或其他因素變化時可能再出現，新客觀變化仍需正常醫療評估。');
  d('d283 d284', '可選肉毒桿菌毒素減少肌肉過度收縮，並處理眼表；半面痙攣部分可評估神經血管減壓等病因治療。', '注射後通常數日開始作用，效果常維持約數月，需要時重複；手術恢復與效果另依病因判斷。', '多能減少痙攣對生活的影響，但注射通常不是永久治癒，可能暫時下垂、複視或乾眼。', '藥效減弱後常會再有痙攣，需要定期調整劑量與注射位置。');

  d('d289 d292 d293 d295 d296 d297 d299', '依眼位、屈光與雙眼功能，選眼鏡、弱視治療、觀察或眼外肌手術；部分複視可用稜鏡協助。', '眼鏡與弱視治療需數週至數月評估，手術後紅與不適常持續數週，眼位穩定可能需數月。', '可改善眼位、頭位與部分雙眼功能，但不保證恢復完整立體視，也不等於治好所有弱視。', '成長與融合能力改變可讓眼位再偏，可能需調整眼鏡或再次手術。');
  d('d290 d291', '先完整矯正遠視，依近遠眼位與功能選是否加近用鏡；仍有殘留角度時才評估其他方式或手術。', '通常戴鏡數週後再比較眼位，之後隨成長長期追蹤；是否能減鏡需逐步評估。', '戴鏡可明顯改善調節相關內偏，但需要的眼鏡不一定能停，弱視要另外治療。', '不戴鏡可能又內偏，度數或眼位也可隨成長改變，需定期調整。');
  d('d294', '檢查確定眼位正常後通常不需斜視治療，仍保留正常的兒童視力篩檢。', '沒有必須完成的用藥或手術療程，外觀可能隨鼻樑及臉型發育改變。', '假性斜視本身不破壞雙眼視覺，但不能只靠照片認定所有偏斜都是假的。', '日後仍可能另發生真正斜視，新偏斜或視力疑慮需再檢查。');
  d('d300 d301 d302 d303 d304', '先矯正度數並處理弱視與眼表保護，再依異常頭位、正前方眼位及肌肉限制評估手術；輕症可觀察。', '通常長期追蹤，手術後需數週至數月評估眼位，複雜情況可能分期。', '主要改善頭位、視軸或外觀，不一定恢復所有方向正常活動；視力仍受先天病因影響。', '構造或神經支配異常仍存在，可能有殘留或再次偏斜，需要再調整。');
  d('d307', '白瞳是警訊而非單一疾病，需立即散瞳及影像查明白內障、腫瘤或視網膜原因後選治療。', '檢查不應延到下一次篩檢；後續從手術後數週到腫瘤或視覺發展的多年照護皆可能。', '預後完全取決於病因，及早發現對保命、保眼及視覺發展都重要。', '不能只因照片不再有白反光就停止評估，後續按確定病因追蹤。');
  d('d309', '多先依指導做淚囊按摩與清潔，明顯分泌物時短期用藥；持續阻塞或反覆感染可評估探通、氣球或插管。', '許多在出生後第一年逐步通暢；介入時機依年齡及症狀個別決定，處置後也可能追蹤數週至數月。', '多數可改善排淚，抗生素只能控制感染，不能把阻塞直接打通。', '鼻塞時流淚可能暫時加重，少數需再次探通；內眼角紅腫痛或發燒需儘速就醫。');
  d('d310 d324', '先確認下垂原因及是否遮擋視軸，依提眼瞼肌功能選手術或觀察；兒童同時矯正散光與弱視。', '手術腫脹多需一至數週，眼瞼高度穩定可到數月；神經或肌肉病因的治療及兒童追蹤更久。', '可改善視軸、視野或頭位，但可能殘留不對稱，必須平衡抬高與閉眼保護。', '年齡、肌肉病程與組織變化可能再下垂，少數需再次調整。');
  d('d311', '新生兒需立即評估病原，依淋病、披衣菌、疱疹或其他原因選全身及局部治療，不能只用一般紅眼眼藥。', '初期可能需住院，療程依病原從數日至數週不等；視力與全身追蹤可更久。', '早期治療通常較有利，侵犯角膜或全身感染可能造成嚴重後果。', '需處理感染來源與相關接觸者，症狀再起要重查，不自行重複舊處方。');
  d('d312', '單純結膜炎依病因處理；眼瞼感染可能需口服或靜脈抗生素，必須先排除眼窩深部感染。', '單純感染常數日至一兩週改善，眼瞼感染需在治療初期確認反應，沒有改善應提早回診。', '表淺病例多可恢復，但眼球運動痛、突出或視力下降代表更嚴重病灶的可能。', '鼻竇、皮膚或眼瞼感染源未處理可能再發，需完成療程及必要追蹤。');
  d('d313', '依散瞳驗光選眼鏡或其他適齡矯正，視需要加弱視或近視控制；不是所有篩檢異常都需要同一種處方。', '配鏡後數週評估適應與視力，成長期間通常定期追蹤數年。', '及早清楚成像有助視覺發展，若已有弱視，改善需要時間與持續治療。', '度數與眼位會隨成長改變，篩檢通過或第一次配鏡後仍需檢查。');
  d('d314 d315 d316', '以屈光矯正、弱視及低視能支持為基礎，依先天病型處理青光眼、眼表或視網膜併發症，必要時全身及遺傳評估。', '多需長期或終生照護，特定手術後恢復以數週至數月計，視覺發展支持持續成長期。', '先天黃斑、虹膜或視網膜構造可能限制最佳視力，但輔具與適合環境可提升功能。', '先天差異不會用短期眼藥消失，後續仍可能出現眼壓、角膜或視網膜問題。');
  d('d318', '先溫敷與眼瞼清潔，影響視力、持續或較大者可選切開刮除或選定類固醇注射；不典型者需病理評估。', '自然縮小常需數週至數月；處置後腫脹通常數日到數週減輕，硬塊不一定立刻全消。', '多為良性阻塞性發炎，通常能改善；兒童較大病灶可能影響散光與弱視。', '瞼板腺或酒糟問題未控制時可再長，同一位置反覆需重新確認診斷。');
  d('d319', '以溫敷與清潔為主，依感染程度加藥；形成明顯膿瘍或向周圍擴散時可能需引流或全身抗生素。', '常數日至一兩週逐步改善，若紅腫擴大或幾天沒有進步應再檢查。', '局限病灶多預後良好，少數留下霰粒腫或擴散為眼瞼感染。', '眼瞼緣炎與腺體問題仍在時可能再發，不擠壓有助減少擴散風險。');
  d('d320 d323', '暫時可潤滑或由醫師拔除倒睫；依眼瞼結構與範圍，選毛囊處置或內翻矯正手術。', '拔睫可較快減輕摩擦，但數週可能再長；手術恢復通常需數週，角膜傷口需另追蹤。', '解除摩擦能保護角膜，已形成的角膜疤痕不一定隨眼瞼矯正恢復。', '睫毛或眼瞼位置可能再異常，部分需重複處理；持續紅痛應檢查角膜。');
  d('d321', '潤滑、夜間保護及避免壓眼，評估睡眠呼吸中止；持續鬆弛磨損時可選眼瞼收緊手術。', '眼表改善可需數週，睡眠及眼瞼問題多需長期照護；手術後腫脹通常數週減輕。', '可改善刺激與暴露，但皮膚、睡眠及組織鬆弛因素仍需處理。', '睡眠壓眼或鬆弛持續時可再不適，術後仍可能需保濕或再次調整。');
  d('d322', '以潤滑先保護眼表，再依鬆弛、疤痕或神經問題選眼瞼收緊、牽引肌修復或皮膚移植。', '手術後腫脹及拉緊感常數週改善，位置與疤痕成熟可需數月。', '可改善暴露與部分流淚，若另有淚道阻塞或乾眼，可能仍需治療。', '組織老化、疤痕收縮或神經問題可能使外翻再出現，少數需再次手術。');
  d('d325', '若主要是皮膚遮擋，可評估上眼瞼整形；眉下垂、真正眼瞼下垂或乾眼需另規劃，輕症也可先觀察。', '腫脹瘀青通常一至數週，疤痕與外形穩定需數月。', '可改善部分視野與沉重感，但不會治療所有視力模糊，切除量須保留足夠閉眼功能。', '年齡相關鬆弛會繼續，效果可能維持多年但不是永久停止老化。');
  d('d327', '先尋找顏面神經病因並及早處理，眼睛用潤滑及夜間保護；無法安全閉眼時可選配重或其他眼瞼保護。', '部分病因可在數週至數月恢復，持續麻痺者可能需長期保護或手術；視角膜狀況提早處理。', '神經恢復程度不一，照護重點是避免角膜受損，不必等神經完全恢復才治眼表。', '部分可再發或留下閉眼不足，新的神經症狀仍需重新評估。');
  d('d328', '典型且穩定的良性病灶可觀察，摩擦、不適或診斷不明時選移除或活檢，不自行剪除。', '小處置傷口常一至數週癒合，病理結果與外觀穩定需依處置範圍追蹤。', '多數預後良好，但要先確認不是外觀相似的惡性病灶。', '某些囊腫或良性增生可能再長，新出現快速變大、潰瘍或掉睫毛應再檢查。');
  d('d329 d330', '以病理確診後規劃完整邊界控制切除與重建，較高風險病型需淋巴結、神經或全身評估，部分再加放射等治療。', '傷口初期癒合約數週，大範圍重建可需數月；腫瘤監測需多年。', '早期完整治療較有利，外觀與功能恢復取決於侵犯及重建範圍；部分病型有轉移風險。', '可局部復發，也可能長出其他日曬相關病灶，需防曬與持續追蹤。');
  d('d335 d336 d337 d338', '先排除感染及腫瘤，必要時影像與活檢，再依確定病因選抗感染、類固醇或免疫調節；有全身病需共同治療。', '部分發炎可數日到數週減輕，但減藥、維持與全身照護常需數月以上。', '壓迫與發炎及早改善較有利，神經或眼外肌已受損可能留下視力或複視問題。', '可反覆，尤其原免疫或全身疾病仍活躍；對類固醇有反應不代表已排除腫瘤。');
  d('d340', '需緊急影像與病理，由兒童腫瘤及眼科團隊選全身化療、放射與適當局部處理。', '通常為數月的多療程治療，完成後仍需多年監測。', '預後受分期、病理與治療反應影響，保護生命優先，再兼顧眼部功能與外觀。', '有復發與治療後長期影響的可能，需規律全身及眼部追蹤。');
  d('d341 d342 d344', '穩定無症狀病灶可觀察，壓迫或出血影響功能時，依病灶流量與位置選手術、介入或其他治療。', '觀察可能多年，介入後腫脹及功能恢復需數週至數月，部分複雜血管病灶可能分次治療。', '良性病灶也可能影響視神經，結果取決於位置與完整控制程度。', '殘留病灶、再出血或囊腫破裂可再出現症狀，突發突出與視力下降需急診。');
  d('d345', '由眼科與耳鼻喉評估鼻竇來源，常需內視鏡引流或開放通道，有感染時加抗感染治療。', '視力受威脅時需立即處理，術後數週到數月追蹤鼻竇與眼窩恢復。', '及早解除壓迫較有利，視神經長期受壓則可能不完全恢復。', '鼻竇通道再阻塞可復發，需完成鼻腔照護與後續追蹤。');
  d('d346 d348', '立即住院給適當靜脈抗生素，依感染、膿瘍或血栓狀況安排引流及跨科治療，並處理鼻竇等來源。', '急性治療需立即開始，住院與抗感染常需數日至數週，嚴重或血栓病變可能更久。', '及早處理有助保護視力與生命，延誤可能造成永久視神經、腦部或其他損害。', '原感染來源未清除或免疫狀態不佳可再發，出院後仍需追蹤。');
  d('d347', '先做血管影像與神經介入評估，依瘻管型態選監測或血管內封閉等處置，並控制眼壓與角膜暴露。', '威脅視力者需急處理，介入後紅腫或複視可在數週至數月逐步改善。', '控制血流可減少眼部壓力，但長期視神經或眼外肌損害可能殘留。', '少數可能再開通或有殘留，需依影像及症狀追蹤。');
  d('d349', '先分辨乾眼刺激、眼瞼位置與真正淚道阻塞；阻塞可依位置選擴張、插管或淚囊鼻腔吻合，非每例流淚都要手術。', '眼表治療可能數週評估，淚道手術恢復需數週，若有支架可能留置數週至數月再拆。', '通道重建能改善阻塞型流淚，但其他刺激或排淚幫浦問題可能仍使流淚持續。', '疤痕再狹窄或其他因素變化可能再次流淚，少數需再處理。');
  d('d350', '依淚小管或淚囊感染選局部／全身抗生素，部分需清除結石、膿瘍或重建阻塞通道。', '急性感染常數日至數週改善，結石與阻塞若需手術，完整處理及恢復可能更久。', '清除感染源與阻塞較能持續改善，單靠反覆點眼藥可能無法根治。', '結石、支架或阻塞仍存在時容易再感染，應追蹤排淚原因。');
  d('d351', '依乾燥、義眼配適、感染或植入物外露原因，選潤滑、義眼調整、藥物或眼窩重建。', '簡單調整可能較快改善，傷口或重建需數週至數月，義眼維護則需長期進行。', '目標是舒適、外觀及義眼穩定，植入物或義眼無法恢復已失去的視力。', '組織收縮、義眼磨損或分泌物可反覆，需定期保養及必要時重新配適。');
  d('d356', '檢查排除異物與其他傷害，以潤滑及適當止痛支持修復，是否用其他眼藥依角膜狀況決定。', '單純表淺紫外線傷常在約 1–3 天改善；持續惡化或視力下降需再檢查。', '大多可恢復，但不當反覆使用麻醉眼藥會妨礙癒合並造成傷害。', '再次電焊或紫外線暴露會再受傷，須使用合格防護。');
  d('d357 d358', '化學傷立即大量沖洗，之後依角膜緣與眼表損傷選保護、抗感染、受監測抗發炎及必要羊膜或重建；熱傷也需評估閉眼與傷口。', '輕傷可能數日至數週改善，重傷常需數月及分階段手術，眼表與眼壓追蹤可持續多年。', '預後取決於深度、角膜緣幹細胞與最初處理速度，重症可留下乾眼、疤痕及永久視力損害。', '不是單純清洗後就結束，之後可反覆破皮、結疤或高眼壓，需要持續照護。');
  d('d359', '用護罩與適當活動限制降低再出血風險，依情況給眼藥並密切量眼壓；量大、眼壓過高或特定風險者可能需手術清除。', '積血常數日至一兩週吸收，前幾天需特別注意再出血；後續青光眼監測需更久。', '小量且無其他傷害者多較有利，角膜血染、再出血或視神經損傷會影響視力。', '初期可再出血，之後也可能延遲發生外傷性青光眼。');
  d('d360', '先評估水晶體、眼壓與眼底，畏光可用濾光或合適接觸鏡，嚴重影響功能再討論虹膜修復等方式。', '急性發炎與不適可能數週改善，但瞳孔及虹膜結構變化可能長期存在。', '輕傷可部分改善，撕裂或根部離斷不一定自行完全恢復，視力也受其他外傷影響。', '不是一般復發病，仍需監測後續眼壓及其他外傷併發症。');
  d('d364 d365', '先排除裂孔、剝離等需處理的共傷，多以追蹤為主；脈絡膜破裂日後若長新生血管可另評估注射。', '表面震盪變化可在數日至數週消退，黃斑功能觀察常需數月，後續新生血管可更晚出現。', '輕微外層損傷可改善，黃斑嚴重受傷或疤痕可能留下中央視力限制。', '日後仍可能有新生血管等併發症，新變形或暗點需提早回診。');
  d('d367 d368', '立即護罩保護並急診，視傷口與異物安排修補、抗感染及必要視網膜處置，之後可能分期重建與光學矯正。', '急性修補不能延誤，傷口癒合與後續手術常需數週至數月，複雜眼部重建可能更久。', '結果取決於傷口位置、感染及視網膜、視神經損傷，先保住眼球再評估可恢復視力。', '後續仍可能有眼內炎、剝離、青光眼或再次傷口問題，需要長期追蹤。');
  d('d371', '依肌肉嵌頓、複視與眼球位置選觀察或骨折修復，兒童夾傷及影響視力者可能需緊急處理。', '腫脹多數週減輕，眼位與神經感覺可能數月才穩定；是否手術不只看受傷經過幾天。', '不少複視可隨消腫改善，嚴重肌肉或神經傷可能殘留症狀。', '骨折不是一般反覆發炎，但可能有殘留眼球內陷或複視，需要後續調整。');
  d('d372', '這是急症，威脅視力時需由受訓醫師立即減壓，之後再處理出血或其他病因；不等待例行檢查。', '搶救視力按分鐘計，減壓後仍需密集監測，傷口與腫脹恢復以數週計。', '視神經缺血時間影響很大，及時減壓仍不能保證完全恢復。', '再出血或壓力再升可再威脅視力，新劇痛、突出或視力下降要即刻處理。');
  d('d373', '先確認眼球完整，再精準修復眼瞼與可能的淚小管，必要時放支架並處理感染風險。', '皮膚與腫脹常一至數週改善，疤痕穩定需數月，淚道支架留置時間依修復情況決定。', '可改善閉眼、眼瞼邊緣與排淚，但嚴重撕裂可能留缺刻、疤痕或流淚。', '疤痕收縮或淚道再狹窄可能需後續調整，支架移位不要自行拉除。');

  d('ird-ad-rp ird-rpgr-xlrp ird-rp2-xlrp ird-cep290 ird-aipl1 ird-gucy2d ird-crb1 ird-rdh12 ird-nmnat1 ird-tulp1 ird-dram2 ird-lord ird-crx ird-cdhr1 ird-cerkl ird-pcare ird-poc1b ird-mak ird-slc7a14 ird-imdh1', '以配鏡、濾光、低視能及行動支持維持生活功能，並處理白內障、水腫等可治療併發症；有明確分子診斷後才評估特定療法或試驗。', '通常是多年甚至終生照護，沒有統一的短期治癒療程；若參與特定治療，另依方案安排，不自行使用高劑量補充品。', '基因與個人差異會影響夜視、中央與周邊視野變化，不能只靠基因名稱預測每年下降多少。', '遺傳差異會持續存在，可能穩定或逐步進展；突然變形、出血或黑幕需另查可治療併發症。');
  d('ird-rpe65', '若證實符合條件的雙等位 RPE65 致病變異且仍有可存活視網膜，可評估 voretigene neparvovec；也需配鏡、視覺復健與長期監測。', '基因治療由專科分眼手術安排，術後需數週照護，功能與安全追蹤延續多年；不是每月一般注射。', '部分低光環境的功能可改善，但不保證正常視力，也不代表所有退化停止。', '仍需監測原疾病、手術及視網膜長期變化；不能把一次治療當作終生免回診。');
  d('ird-hjmd ird-stgd3 ird-stgd4 ird-doyne ird-ncmd ird-cacd ird-imp-vitelliform ird-sveinsson ird-rp1l1', '以黃斑影像、配鏡及低視能支持為主；若出現新生血管，可選抗血管新生治療，沒有活動性滲漏時不一律注射。', '通常需長期追蹤，功能可能多年變化；併發新生血管時以數週到數月評估治療反應。', '有些類型相對穩定，有些逐漸萎縮，現有治療不一定能恢復已流失的中央感光細胞。', '基因或發育特徵持續存在，新滲漏與新生血管可能再發；新暗點或變形應提早回診。');
  d('ird-md-rp-overlap ird-macular-dystrophy-heterogeneous ird-laurence-moon ird-adipor1', '先釐清真正病型與變異證據，再安排對應的視覺、全身或遺傳照護；未確診前不套用其他疾病的治療。', '分子與臨床評估可能需要多次檢查，之後通常長期追蹤；沒有適用所有此類名稱的固定療程。', '這些分類或少見關聯不能單獨預測視力，需依個別影像、電生理與病程判斷。', '是否進展及是否有可治療併發症需追蹤確認，意義未明變異不等於已確診。');
  d('ird-arb ird-enhanced-s-cone ird-best1-advrc', '定期評估黃斑積液、屈光、眼壓與隅角，依實際併發症選藥物、雷射或手術，並提供低視能支持。', '多需長期照護，積液或眼壓治療常以數週至數月評估，再依反應維持。', '處理併發症有機會改善功能，但不能保證改變所有先天視網膜特性。', '積液、眼壓或其他結構問題可能再出現，基因相關追蹤仍需持續。');
  d('ird-kcnv2 ird-bradyopsia ird-bornholm ird-oligocone ird-blue-cone ird-xl-csnb-complete ird-xl-csnb-incomplete ird-ar-csnb ird-riggs-csnb', '以正確配鏡、濾光、改善照明與學習環境為主，必要時視覺復健；先以功能及基因檢查確認類型。', '通常長期支持，沒有一段一般眼藥療程可以改變先天訊號傳遞；成長時需持續調整。', '部分功能相對穩定，但畏光、色覺、夜視或對焦限制可能長期存在，不一定達正常視力。', '不屬一般感染的復發，若功能持續下降或有新症狀仍需重新評估。');
  d('ird-norrie ird-wagner ird-knobloch ird-snowflake ird-kif11 ird-incontinentia', '依血管發育、周邊裂孔與牽引狀況選雷射、手術或觀察，並處理弱視、配鏡及相關全身需求。', '兒童期可能需密集檢查與分次處置，術後恢復以週到月計，後續追蹤延續多年。', '視力受先天發育與是否已剝離影響，早期處理能減少部分可避免的損害。', '原構造仍在，可能有新的牽引、血管活動或剝離，不能只依目前看得清楚停止追蹤。');
  d('ird-pxe', '監測黃斑並防止眼部撞擊，出現新生血管時可評估抗血管新生注射；相關皮膚與血管問題由專科共同照護。', '需要長期監測，活動性新生血管常先按月追蹤治療反應，再依病況調整。', '治療可控制部分滲漏，但原有膜層脆弱、萎縮或疤痕不一定恢復。', '可再出血或長新血管，新變形或暗點應儘快檢查。');
  d('ird-bothnia', '以夜間照明、配鏡及低視能支持為主，依病型與併發症作個別治療，避免自行高劑量補充。', '屬長期照護，暗適應與視網膜功能需多年追蹤，沒有一般短期眼藥療程。', '病型可有不同程度進展，改善環境能幫助行動，但不能保證恢復正常夜視。', '不是感染再發，應追蹤是否有新的中央或周邊視覺變化。');
  d('ird-midd ird-narp ird-alstrom ird-senior-loken ird-joubert ird-mainzer ird-sensenbrenner ird-cohen ird-pharc ird-boucher-neuhauser ird-oliver-mcfarlane ird-jalili ird-morm ird-heimler ird-zellweger ird-kjellin ird-mucolipidosis-iv ird-c8orf37 ird-ift172 ird-dhdds ird-hgsnat ird-mfsd8 ird-mvk ird-klhl7', '眼科處理屈光與可治療併發症，並提供視覺支持；依確定病型結合神經、腎臟、聽力、內分泌或其他專科，部分代謝或神經病另有特定治療。', '多是長期、多專科照護，特定藥物或手術的療程另外訂定，不能只用一段眼藥代表整個疾病治療。', '結果取決於基因型與各器官受累，眼睛外觀或單次視力不能預測全身病程。', '遺傳病因持續存在，可有不同器官後續表現；需按實際病型追蹤，並非所有變異都有相同風險。');
  d('ird-kearns-sayre', '需神經、心臟與眼科共同照護，尤其監測心臟傳導；眼部以潤滑、配鏡及選定的下垂或視覺支持為主。', '需要長期心臟與神經監測，眼部手術只能處理部分功能，不會結束粒線體疾病病程。', '視網膜與眼肌影響程度不一，暈厥或心悸等全身警訊比外觀改變更急迫。', '可隨時間有新的全身表現；不是一段短療程後即可停止追蹤。');
  d('ird-mtp', '遵守代謝專科的飲食、避免空腹及生病應變計畫，並追蹤心臟、肌肉與視網膜；視覺支持依需要提供。', '代謝照護通常終生持續，生病時可能需即刻調整，視網膜監測則長期進行。', '控制代謝危機很重要，但眼底退化仍可能進展，不能只看平時血液穩定就省略眼科。', '感染、空腹或能量不足時可有代謝惡化，需要清楚的急症計畫。');
  d('ird-refsum', '由代謝專科規劃低植烷酸飲食，嚴重時評估血漿處理，並監測神經、心臟、聽力及視網膜。', '飲食與代謝管理通常需終生，不能靠短期禁食；改善及功能監測以月到年計。', '適當控制可改善部分全身問題，但既有視網膜退化通常不能完全逆轉。', '停飲食控制、快速減重或代謝壓力可再惡化，應依專科計畫處理。');
  d('ird-abetalipoproteinemia ird-aved', '以專科監測下的營養及適當維生素替代為重點，依疾病調整吸收與飲食，並追蹤神經和視網膜。', '通常需長期甚至終生補充與檢驗，不是服幾週一般保健品即可結束。', '及早補足有助減少後續損害，已萎縮的神經或視網膜功能不一定恢復。', '缺乏原因仍存在，停止補充或吸收變差時可再次影響控制。');
  d('ird-ctx', '儘早由代謝或神經專科評估 chenodeoxycholic acid 等病因治療，另處理白內障及視覺需求。', '病因治療通常長期持續，神經與代謝反應以月到年評估；眼部手術恢復另依程序安排。', '早期處理較能減少累積損害，但已有的神經或視網膜傷害未必逆轉。', '需要持續代謝控制與監測，不能只因白內障手術看清楚就停止全身治療。');
  d('ird-ncl', '先確認確切基因型，依類型評估已核准的特定治療或試驗，並安排癲癇、發展、營養與視覺支持。', '通常需長期神經與代謝照護，特定治療有各自的反覆給藥與監測計畫。', '不同類型差異大，某一病型可用的療法不能套用全部；視覺恢復與全身控制也不一定相同。', '多屬持續疾病而非單次感染，需追蹤進展與新的功能需求。');
  d('ird-lhon ird-dnajc30-lhon ird-opa1 ird-opa1-plus ird-wfs1 ird-opa3 ird-tmem126a ird-aco2 ird-rtn4ip1 ird-ssbp1 ird-nr2f1', '先整合基因與視神經表現，依病型評估特定藥物或研究；提供配鏡、低視能及相關全身、聽力或發展照護。', '通常需多年照護，若有特定藥物常以數月以上評估；兒童視覺與全身需求需隨成長調整。', '部分病型可改善或保持穩定，部分會進展；已萎縮的視神經不一定能恢復正常。', '基因差異持續存在，需監測另一眼與全身表現；家庭風險須依核基因或粒線體遺傳分別說明。');
  d('ird-mactel2', '以影像及功能追蹤，成人可評估美國已核准的 ENCELTO 細胞植入治療及當地可近性；合併新生血管時另選注射等方式。', '細胞植入是專科手術而非一般每月注射，術後需數週照護與長期監測；新生血管療程另依活動性決定。', '目標是減緩特定結構惡化並維持功能，不是把已流失的感光細胞完全長回。', '通常屬慢性變化，仍可能出現新生血管或進展，並非典型單基因疾病的復發模式。');
  d('ird-capn5', '同時控制發炎、眼壓、缺血與牽引，依需要選免疫治療、雷射或手術，並提供遺傳與視覺支持。', '常需長期綜合照護，活動期療程以週到月計，手術後仍需多年監測。', '可處理部分可逆問題，但慢性發炎與牽引造成的損害可能留下視力限制。', '發炎、新生血管及牽引可反覆或進展，治療不能只靠一次手術。');

  p('p0 p1 p2 p4', '症狀輕可先調眼鏡與照明；已影響生活時，依白內障硬度、眼部條件與需求選取出方式及人工水晶體。雷射輔助不是人人必需。', '多為一次手術，視覺可在數日開始改善，傷口與度數穩定通常約 4–8 週；較大切口或複雜眼睛可能更久。', '主要改善白內障造成的模糊，原有視網膜或視神經病仍會限制視力；手術後仍可能需眼鏡。', '白內障本身不會重新長回，但後囊可能日後混濁，屆時可評估雷射。');
  p('p3 p16', '這類水晶體處置多用在脫位或特定複雜情況，會比較可保留的支撐、手術路徑與後續鏡片矯正方式。', '通常需一次或分期手術，恢復常數週至數月，合併玻璃體或視網膜問題時可能更久。', '去除水晶體問題後仍要重建對焦，最終視力取決於其他構造是否健康。', '可能有殘留度數、眼壓或鏡片固定問題，需追加處置與長期追蹤。');
  p('p5', '影響視覺發展時需考慮及早手術；是否同時放人工水晶體，須比較年齡、接觸鏡照護能力及後續風險。', '手術後傷口恢復以數週計，但配鏡與弱視治療常需數年，並長期監測眼壓。', '建立清楚視軸只是第一步，視力仍受病因、治療時機與弱視程度影響。', '可能再次視軸混濁、眼壓上升或需要更換矯正方式，不能手術後就停診。');
  p('p6 p7', '這是讓複雜白內障手術更安全的輔助方式，會依囊袋支撐或瞳孔狀況選裝置，不是每位患者都需要。', '多與白內障同次完成，恢復通常數週，發炎較重或需額外固定者可能需數月。', '輔助裝置提高操作與支撐條件，但不保證完全避免囊袋、虹膜或其他併發症。', '原本支撐弱或組織病變可能持續，之後仍需留意鏡片位置與眼壓。');
  p('p8 p9', '可比較分次手術或一次同時處理白內障與青光眼；是否合併及採哪種降壓方式，要看目標眼壓與隅角等條件。', '通常一次手術處理兩項問題，前幾週到數月需較密集調整眼藥與眼壓，長期仍要追蹤視神經。', '可改善水晶體混濁並降低眼壓，但不會恢復已失去的視野，也不保證完全停藥。', '降壓通路可能結疤或效果不足，之後可能需加藥、雷射或再次手術。');
  p('p10-p15 p93', '囊袋不足或鏡片有問題時，可比較眼鏡、接觸鏡、重新固定與更換鏡片；固定於虹膜或鞏膜各有適用條件。', '多為一次或分期手術，視力與度數穩定常需數週至數月，合併視網膜處置會延長恢復。', '可改善對焦、偏心或重影，角膜、黃斑及原外傷仍會影響最終清晰度。', '鏡片或固定材料可能日後再偏位、外露或失效，需持續追蹤。');
  p('p17 p101', '確認模糊是後囊混濁時，門診雷射通常比再次換鏡片更合適；若原因是黃斑或鏡片位置，就需其他處理。', '多數一次門診即可完成，視覺可能數日改善，短期需依眼壓與眼底安排回診。', '可改善混濁造成的視力下降，但不能治療其他眼病，也可能出現暫時飛蚊。', '開口通常可維持，少數需擴大；日後新模糊仍需重新找原因。');
  p('p18', '這是處理術中玻璃體脫出的安全步驟，醫師依實際情況決定切除範圍及鏡片位置，必要時分期處理。', '多在原手術當下完成，之後恢復可能比一般白內障更久，常需數週至數月觀察。', '目標是減少玻璃體拉扯與傷口問題，最終視力取決於合併損傷及後續發炎。', '仍可能有黃斑水腫、視網膜問題或需追加手術，應按較密集時程回診。');
  p('p19 p20', '當鏡片等方法不足時，可依病變層次選全層或前板層移植；保留健康內皮有其優點，但不是每個角膜都適用。', '多為一次移植，但視力、散光與縫線管理常需數月到一年以上；傷口長期仍需防撞。', '可改善混濁，但術後常仍需眼鏡或接觸鏡，結果受原病、眼壓與眼底狀態影響。', '可能排斥、失能或原沉積再出現，少數需再次移植；多年後也要注意紅痛與變糊。');
  p('p21 p22', '內皮失能時可比較不同厚度的內皮移植，若其他角膜層也嚴重受損可能需全層；以眼藥只能暫時緩解部分水腫。', '視力常數週至數月改善，初期依指示配合氣泡姿勢；抗排斥與眼壓監測可能長期持續。', '其他構造健康時有良好改善機會，但移植物脫離可能需補氣，內皮與視力恢復速度因人而異。', '移植物可排斥或逐漸失能，需長期追蹤，不能因沒有表面大縫線就忽略。');
  p('p23', '多在一般角膜移植不適合或反覆失敗時考慮，須先比較保留自然角膜與其他重建方式，以及長期照護能力。', '手術後恢復需數週至數月，但眼藥、可能的保護鏡片及感染與眼壓監測通常是終生安排。', '可提供透明光路，視力仍受視神經、視網膜與嚴重眼表病影響；不是免維護的人工鏡片。', '可有膜形成、角膜融解、感染或青光眼，需要追加處置甚至更換。');
  p('p24 p25', '確認角膜持續擴張後評估交聯；鏡片改善視力與交聯穩定角膜的目標不同，去上皮與保留上皮方案需比較證據及安全條件。', '通常一次治療，去上皮後表皮常約一週修復，視力與角膜形狀可能數月才穩定，之後仍長期比較是否進展。', '主要是減緩惡化，不能保證視力變好或角膜恢復正常；部分仍需特殊鏡片。', '少數仍可能進展或需再次處理，避免揉眼及控制過敏很重要。');
  p('p26', '可與特殊鏡片、交聯或角膜移植比較；環段以改善形狀為主，若仍在擴張，可能另外需要交聯。', '多為一次植入，短期數週恢復，度數與視覺品質常需數月評估。', '部分可改善鏡片耐受及不規則散光，但不保證不戴鏡，也不一定阻止病程。', '可能移位、外露或效果不佳而需調整或取出，原角膜疾病仍需監測。');
  p('p27 p28 p29 p37', '先比較潤滑、眼藥或保護鏡片，持續疼痛或表面病灶影響視力時，再依位置與深度選清創、拋光、穿刺或雷射。', '多為一次表面處理，上皮通常數日至約一週修復，視力與角膜規則性可能數週至數月穩定。', '可改善反覆破皮、表面混濁或不規則，但深部疤痕不一定能靠表面處置消除。', '乾眼、基底膜或沉積病因仍在時可能再發，仍需保養或重複處置。');
  p('p30 p95 p144 p155 p180', '當一般檢查不足以決定治療時，會比較採樣的必要性、位置與風險；目的是確診或分期，不是採樣本身就能治好所有病因。', '採樣通常一次，傷口恢復數日至數週，檢驗可能數日至數週才完整；後續療程依結果決定。', '結果可幫助選正確治療，少量或非代表性檢體可能無法確診，需結合影像及病程。', '若檢體不足或病情變化，可能需再次採樣；復發風險取決於最後確定的疾病。');
  p('p31', '羊膜是眼表修復的輔助，可與潤滑、保護鏡片、其他移植物或眼瞼保護比較；仍須治療感染或免疫病因。', '覆蓋或移植通常一次，羊膜吸收與上皮修復需數日至數週，嚴重眼表病可能需數月與再次處置。', '可提供修復環境，但不能保證補回所有角膜緣細胞或逆轉深層疤痕。', '原疾病活動時傷口可再破，羊膜也可能需重複使用或改用其他重建。');
  p('p32', '症狀輕可先防曬與潤滑，影響視力、角膜形狀或持續不適時評估切除；會比較移植固定與復發風險。', '通常一次手術，表面恢復數週，紅眼與度數穩定可能需一至數月。', '可改善病灶引起的刺激或部分散光，既有中央疤痕不一定消失。', '仍可能再長，持續防曬與照護眼表，復發時需再評估。');
  p('p33', '先穩定眼表與眼瞼，再比較自體、異體或培養細胞來源；雙眼疾病與供體風險會影響選擇。', '常需分階段治療，眼表穩定以數月計，後續角膜手術可能另安排；異體來源可能需長期全身免疫藥。', '目標先恢復可持續修復的表面，再改善透明度與視力，不一定一次完成。', '發炎、排斥或原病可使幹細胞功能再次不足，需長期監測。');
  p('p34 p35', '依缺損大小與感染狀態，可比較組織膠、覆蓋瓣與角膜移植；主要先保住眼球結構，再規劃視覺重建。', '常為急性穩定處置，數日內需密切檢查，後續修復與可能的再次手術以週到月計。', '可暫時或長期封閉與保護病灶，但中央覆蓋或疤痕可能限制視力。', '滲漏、感染或融解可能再出現，不能當成貼好後就永遠安全。');
  p('p36 p140 p141', '眼表無法安全暴露時，可比較潤滑、保濕罩、暫時眼瞼縫合或配重與其他眼瞼重建。', '傷口多一至數週修復，保護需持續到閉眼安全；縫合可暫時或較長期，配重需後續檢查。', '主要保護角膜而不是直接提升視力，需要平衡眼裂、外觀與閉眼功能。', '神經或眼瞼問題仍在時可能再暴露，材料移位或效果改變可需修正。');
  p('p38', '先確認排斥而非感染，再密集抗發炎並監測眼壓；若移植物已不可逆失能才評估再次移植。', '急性治療需立即開始，數日後評估反應，逐步減藥常需數週至數月，維持療程可能更久。', '及早處理較可能挽救透明度，嚴重內皮損傷不一定能恢復。', '日後仍可再次排斥，需要依指示持續用藥與留意警訊。');
  p('p39 p40', '依角膜穩定度比較眼鏡、特殊鏡片、縫線調整與其他散光手術，不一定需要把所有縫線一次拆完。', '可能分次調整，拆線或處置後度數需數週至數月重新穩定，移植後整體管理可能一年以上。', '可改善部分散光與配鏡條件，但不規則角膜不一定變成完全規則。', '傷口形狀與度數仍可能改變，可能需再次配鏡或調整，鬆線要回診。');
  p('p41 p191', '眼鏡與接觸鏡仍是替代選擇，是否屈光手術需比較角膜條件、度數、乾眼及近遠視覺需求，不能只看想不想摘鏡。', '多為一次手術，部分數日可恢復日常視覺，度數、乾眼與夜視適應可能需數週至數月。', '可減少對眼鏡依賴，但仍可能有殘留度數、光暈或乾眼，原高度近視眼底風險不會消失。', '度數回退或老花可讓之後再需眼鏡；是否可追加手術需重新檢查，不能無限次切削。');
  p('p42 p43', '可與眼鏡、接觸鏡、其他角膜或鏡片手術比較；表面手術無角膜瓣，但仍須有足夠厚度與適當眼表。', '多為一次處理，表皮常約一週修復，初期較痛與模糊，視力及度數穩定可需數週至數月。', '可改善屈光，但可能霧化、乾眼或殘留度數，不能保證完全不戴鏡。', '度數可回退，是否追加取決於穩定度與安全厚度，角膜擴張風險仍需監測。');
  p('p44 p45 p46 p47', '依前房、內皮、原水晶體與近視程度，比較眼鏡、接觸鏡、角膜雷射或不同鏡片／切口方式，並說明調節力的取捨。', '多為一次手術，初期恢復數日到數週，度數與視覺適應常需數週以上；部分裝置需要長期內皮及眼壓監測。', '可減少部分眼鏡依賴，但鏡片位置、夜視、老花與視網膜狀態會影響結果。', '度數、眼壓或鏡片位置可能改變，少數需更換、移除或追加矯正。');
  p('p48 p49', '這些多屬歷史或受限技術，現今會比較眼鏡、接觸鏡及較適合的其他方式；既有手術者重點是處理晚期變化。', '既有植入物或切口需長期追蹤，若需修復，度數可能數月才穩定。', '可改善特定問題，但舊手術造成的混濁、波動或傷口脆弱不一定完全逆轉。', '仍可能有度數漂移、混濁或傷口問題，不是一次修正就終止所有後續風險。');
  p('p50 p51 p52', '先釐清是殘留度數、角膜擴張、界面發炎或角膜瓣問題，再比較眼鏡、鏡片、交聯或修復手術，不能一律追加雷射。', '處置可能一次或分期，表面恢復以日到週計，角膜與視力穩定常需數月。', '目標可能是穩定角膜或改善視覺，兩者不同；嚴重疤痕或擴張會限制結果。', '原問題可能持續或復發，仍需影像、眼壓與最佳矯正視力追蹤。');
  p('p53-p56 p61 p62', '依目標眼壓與病型，比較眼藥、雷射、隅角手術、濾過或引流裝置；不是所有青光眼都需要相同通路。', '多為一次手術，前數週至數月需密集調整眼藥與引流，之後仍終生或長期追蹤。', '目標是保住剩餘視野，不能恢復已壞的視神經，也不保證完全停藥。', '疤痕會使引流效果減弱，可能需針撥、加藥或再次手術。');
  p('p57-p60', '依原手術、結膜與眼壓，比較不同引流管、濾過或其他降壓方式；修正管路時也需處理外露或阻塞的原因。', '傷口與包膜變化常需數週至數月，無閥裝置的引流時程另有安排，初期回診通常較密。', '可降低眼壓並減少疼痛或進一步損害，但剩餘視力取決於原疾病。', '管路可能阻塞、外露或被疤痕限制，可能需修正或追加治療。');
  p('p63-p68', '依隅角與降壓目標，比較藥物、雷射與不同隅角手術；若需很低眼壓，可能要選其他濾過或引流方式。', '常為一次手術，可與白內障合併，前數週觀察眼壓與出血，效果通常需數週評估。', '可減少眼壓或部分藥物負擔，但效果受天然排水系統限制，不能保證停藥。', '眼壓可能再升或病程繼續進展，日後仍可能需其他青光眼處置。');
  p('p69-p72 p104', '可與其他眼藥、引流或濾過手術比較，依剩餘視力及病型選連續波、微脈衝、內視鏡或冷凍等方式。', '多一次處理後數週評估眼壓，發炎與藥物調整可能持續更久，部分需重複治療。', '主要降低眼壓與疼痛，不會修復已損傷視神經；較低組織破壞也不等於完全無風險。', '效果可不足或減弱，可能再做或改選其他手術，仍要注意低眼壓及視力變化。');
  p('p73 p74', '依角膜透明度與排水構造選隅角或外路小樑切開，藥物多為輔助；若效果不足可能需其他兒童青光眼手術。', '手術後數週至數月密集檢查，部分需再次麻醉檢查，之後追蹤延續成長期甚至終生。', '及早控制有助保護視神經，仍需配鏡與弱視治療，不能只看眼壓下降。', '排水效果可隨組織改變而不足，可能需要再次手術。');
  p('p75 p102', '這是調整既有濾過手術效果的方式，會比較眼藥、針撥、縫線調整或正式修正，不適合每個高眼壓情況。', '常是一次門診或小處置，眼壓可能很快改變，之後數日到數週需密集檢查。', '可改善部分疤痕或流量限制，仍可能眼壓過低或效果不足。', '疤痕與引流可再次變化，少數需重複針撥或進一步手術。');
  p('p76 p77', '先確定是漏水、過度引流還是其他原因，再選藥物、保護、縫補或重建；不同機轉的治療可能不同。', '威脅眼球或感染風險時需及時處理，之後數日到數週密集檢查，恢復可延續數月。', '目標是恢復合適眼壓與完整結構，長期黃斑或角膜損傷可能限制視力。', '可能再次滲漏、低眼壓或之後眼壓偏高，需持續調整。');
  p('p78 p79 p80 p81', '依裂孔、牽引及水晶體狀態比較玻璃體切除、扣壓或氣體復位，部分需要合併；不是每種剝離都適用同一術式。', '常一次或分期手術，初期恢復約 2–6 週，視力改善可能需數月；氣體姿勢及限制另按實際情況安排。', '視網膜復位與恢復原視力不同，黃斑是否受累與持續時間影響很大。', '可再次剝離或需取矽油、處理白內障等後續手術，仍需長期追蹤。');
  p('p82', '症狀輕或穩定可觀察，影響閱讀與生活時比較手術與繼續觀察的取捨；眼藥不能直接移除牽引膜。', '多一次手術，初期數週恢復，變形與視力常需數月慢慢改善。', '可減少牽引，並非每人都回到原本視力，長期感光細胞損傷可能殘留。', '膜可能再形成，少數需再手術；新中央暗點或明顯惡化應回診。');
  p('p83 p84', '依裂孔大小、病程與既往手術選內界膜剝除或特殊瓣技術；較大或難治病例的策略不同。', '通常一次手術後依指示配合姿勢，傷口恢復數週，視力改善可需數月，氣體未吸收前仍有活動限制。', '裂孔閉合不等於視覺完全正常，孔洞大小與時間會影響最終結果。', '可能未閉合或再開，需依影像討論追加治療。');
  p('p85', '依出血時間、厚度與來源，比較注射、氣體移位、溶血輔助或玻璃體手術，並持續治療出血的新生血管。', '初期決策需及早，積血吸收與黃斑恢復常需數週至數月，原病注射可能更久。', '移開積血可減少部分傷害，已受損的黃斑不一定完全恢復。', '原血管病仍可再出血，需要長期影像與病因控制。');
  p('p86 p90 p91 p92', '依嚴重牽引、巨大裂孔或兒童構造選分膜、扣壓、切開與填充物，目標先讓視網膜可安全復位。', '可能需多次或分期手術，傷口恢復數週，視力與解剖穩定常需數月以上。', '可保留眼球與部分功能，但嚴重缺血、黃斑損傷與疤痕會限制視力。', '複雜剝離較可能再收縮或剝離，少數需長期矽油或再次手術。');
  p('p87 p89', '氣體與矽油的支撐時間、姿勢、旅行限制及取出需求不同，依裂孔位置與病情選擇，不是越久或越重就一定越好。', '氣體逐步吸收，時間依種類、濃度與眼睛而異；矽油通常另評估何時移除，不能用固定週數自行解除限制。', '填充物提供暫時支撐，不直接讓視網膜恢復功能，視力受原病及填充物影響。', '原剝離可再發，矽油可乳化或影響眼壓，可能需移除或再次填充。');
  p('p88', '在視網膜已足夠穩定且風險可接受時考慮移除，也要比較繼續留油的角膜與眼壓負擔。', '多一次手術，初期恢復數週；若再放氣體，姿勢及飛行限制需重新依氣泡安排。', '可減少矽油相關問題，視力不一定明顯變好，仍受原剝離與黃斑損傷限制。', '移除後可能再剝離或需重新填充，需按期確認視網膜。');
  p('p94', '依疼痛、眼壓、脈絡膜貼合及血塊狀態，比較密切觀察、引流或合併玻璃體手術，時機需個別決定。', '引流後恢復以數週至數月計，等待與手術時機不能一律套用固定天數。', '主要減少擠壓與結構傷害，原出血對視網膜及視神經的損傷可能已限制視力。', '可再出血、低眼壓或剝離，少數需再次處理。');
  p('p96 p118', '依病因選抗血管新生、類固醇、抗感染或其他眼內藥物；部分可與雷射、觀察或手術比較，但藥物不可互相替代。', '慢性黃斑病常先按月評估再調整間隔，可能需數月到數年；眼內感染等急症則有更密集療程，並非所有注射都按月。', '可改善部分滲漏或控制感染與發炎，既有缺血、疤痕或萎縮不一定恢復。', '原病可能再活動而需追加，不能因打過一次或暫時看清楚就自行停診。');
  p('p97 p98', '先確認是瞳孔阻滯或周邊虹膜構造問題，再比較虹膜切開、成形、眼藥與水晶體處理；不同機轉不應互換。', '多為一次門診雷射，當日及之後數日到數週看眼壓與發炎，必要時補打或再評估隅角。', '可解除部分阻塞，已形成沾黏或青光眼損害不一定逆轉。', '開口或隅角狀態可能再變化，高原虹膜等仍可閉鎖，需長期追蹤。');
  p('p99 p100', '可與降眼壓眼藥或其他手術比較，適用於合適的開放隅角；選擇性與氬雷射的組織作用及重複空間不同。', '通常門診完成，降壓效果多需數週評估，原眼藥是否減量須看反應。', '可降低部分眼壓或藥物負擔，不能修復已失去的視野，也不能保證每人有效。', '效果可隨時間減弱，可能需再雷射、加藥或手術。');
  p('p103', '先排除裂孔並評估飛蚊對生活的影響，可選觀察適應、特定雷射或玻璃體手術，後兩者都有風險與選例限制。', '可能一次或多次處理，效果在數日到數週評估；不保證處理完所有混濁。', '部分患者困擾可減輕，但視網膜、鏡片與眼壓風險需衡量，不能稱為普遍安全的飛蚊根治法。', '新的混濁或未處理飛蚊仍可能存在，新閃光或黑幕要急查。');
  p('p105', '依新生血管與回診能力，比較周邊雷射、抗血管新生注射或合併方式；有積血或牽引時可能需手術。', '雷射常一次或分次完成，反應以數週評估，之後仍需數月到長期追蹤。', '主要降低嚴重出血與剝離風險，可能犧牲部分夜視或周邊視野，並非以增加現有視力為唯一目標。', '新生血管可再長，可能需補雷射或加注射。');
  p('p106 p107', '依病因與滲漏位置比較注射、觀察、局部或微脈衝雷射；中央受累的多種水腫通常需先考慮其他有效治療。', '可一次或分次處理，效果常以數週至數月評估，原病監測仍需長期。', '目標是控制特定滲漏或水腫，不能保證改善缺血所致視力下降，低能量也不是完全無風險。', '積液可能再出現，可能需重複雷射或改選注射等方式。');
  p('p108', '依裂孔牽引與症狀比較雷射、冷凍或觀察，已有明顯剝離時常需其他手術。', '多一次門診完成，黏著及初期確認約一至數週，之後依風險安排複查。', '可降低部分裂孔進展為剝離的風險，但不保證所有飛蚊消失或永不剝離。', '其他位置仍可有新裂孔，必要時補打，出現黑幕或新症狀應立即檢查。');
  p('p109', '依病因比較光動力、抗血管新生注射、其他雷射或觀察，中心性漿液病與新生血管使用的參數及目標不同。', '多為一次門診療程，再於數週至數月看積液與病灶反應，部分需重複或合併治療。', '可控制特定異常血管或滲漏，長期萎縮與疤痕不一定恢復。', '病灶可能再活躍，需依影像討論再次治療；給藥後按指定時間避強光。');
  p('p110 p178', '屬特定病灶的熱療選項，需與放射、注射或其他局部治療比較，不能視為所有眼底腫瘤或黃斑病的標準首選。', '可一次或分次處理，病灶反應需數週至數月觀察，長期追蹤原疾病。', '可控制部分病灶，但熱傷害與原病會影響視力，治療成功不等於無後遺症。', '可能殘留或復發，需追加或改用其他方式。');
  p('p111', '取樣是為釐清特定病因，降壓則是暫時處理危險高壓，後續仍需解決原因；不是視網膜動脈阻塞的常規治療。', '多一次小處置，眼壓需短時間內再量，傷口數日觀察，真正疾病的療程另依結果安排。', '可取得檢體或暫時改善壓力，但不能保證一次穿刺解決所有問題。', '眼壓原因仍在時可再升，或檢體不足需再採樣，須評估利益與感染風險。');
  p('p112', '先確認沒有穿透傷，再決定移除深度；深層或高速異物可能需影像與手術，而非一般門診挑除。', '表面異物常一次處理，小傷口多數日癒合，鏽環或深傷可能需分次及數週追蹤。', '可改善摩擦與疼痛，中央或深部疤痕可能影響視力。', '殘留異物、感染或反覆糜爛可能需追加處理，工作時持續防護。');
  p('p113 p132', '可先溫敷觀察，持續或影響功能時比較切開刮除與病灶內注射；反覆、不典型病灶應先規劃病理。', '通常一次處置，腫脹與殘留硬塊可需數日至數週消退。', '多能改善阻塞結節，但不是治好所有瞼板腺疾病；切除或注射也可能留疤或色素變化。', '可能再長或在別處出現，持續眼瞼保養；同處反覆要重新確認診斷。');
  p('p114', '先治療眼表發炎，再比較可移除塞子、永久燒灼與其他乾眼治療，排淚感染或過度流淚者不一定適合。', '塞子放置多一次門診完成，數週評估舒適與流淚；燒灼癒合數日至數週，乾眼照護仍長期持續。', '可增加淚液停留，但不能補回所有淚腺功能，可能仍需人工淚液。', '塞子可脫落、通道可再開或過度流淚，需取出、調整或再次處置。');
  p('p115 p142 p170', '依痙攣或斜視病型比較藥物、稜鏡、手術與肉毒桿菌毒素，劑量依產品與肌肉選擇。', '注射後通常數日開始作用，常維持約數月，是否重複與間隔依效果及副作用調整。', '可暫時減少肌肉過度作用，但不一定永久改變原病；短暫下垂、乾眼或複視可能發生。', '藥效消退後症狀可能回來，常需重複注射或改其他策略。');
  p('p116', '依病灶位置與藥物需求，比較眼藥、眼周注射、眼內或全身治療，不能只因注射較直接就認為效果一定較好。', '通常一次後評估，藥效從數日至數月依製劑不同；感染或慢性發炎需另外安排療程。', '可提供局部藥效，原病與藥物副作用仍影響結果，類固醇需監測眼壓。', '原病可能再活躍而需追加，長效藥的副作用也可能延續較久。');
  p('p117 p130', '少量可暫時拔除，反覆或多發時比較電解、冷凍、雷射或眼瞼重建；有內翻時需處理位置病因。', '拔睫立即減少摩擦但數週可能再長，毛囊或眼瞼手術需數日至數週恢復，可能分次。', '目標是減少角膜磨損，已形成的角膜疤痕不一定恢復。', '毛囊殘留或眼瞼病因仍在時可能再長，需要重複治療。');
  p('p119-p122', '依提肌功能、下垂病因與角膜保護比較提肌、眼瞼內側或額肌懸吊方式；不影響視軸的部分病例可先觀察。', '若選手術，腫脹常一至數週減輕，高度與疤痕穩定可能需數月；兒童仍需弱視追蹤。', '可改善視野與頭位，但需平衡左右高度與閉眼安全，不保證完全對稱。', '下垂或不對稱可能再出現，必要時再調整，持續閉眼不足須保護角膜。');
  p('p123-p125', '先分辨皮膚、脂肪、眉位與真正下垂問題，再選合適整形方式；外觀需求也需衡量乾眼與閉眼風險。', '通常一次手術，瘀青腫脹常一至三週，外觀與疤痕可能數月才穩定。', '可改善部分遮擋與外觀，不會治療所有視力模糊，不能保證完全對稱。', '老化與組織鬆弛持續，效果並非永遠不變，少數需修正。');
  p('p126-p129 p131', '依水平鬆弛、疤痕與牽引肌問題比較縫線、收緊、移植或組合修復，潤滑可暫時保護角膜。', '多一次或分期手術，腫脹與拉緊感常數週改善，位置與疤痕穩定需數月。', '可改善眼瞼位置與部分流淚，合併淚道或眼表病者可能仍有症狀。', '組織老化或疤痕可使位置再變，少數需再次手術。');
  p('p133 p134 p187 p188', '依疑似病因、病理與範圍選活檢、邊界控制切除、冷凍或局部藥物，先確認診斷與邊界再談重建。', '小切除後通常數週恢復，分期邊界或局部藥物可能需數週至數月，腫瘤監測需多年。', '目標是安全控制病灶並保留功能，結果取決於病理、侵犯深度與眼表狀況。', '可有殘留或復發而需追加，外觀看不到病灶也仍要依病理安排追蹤。');
  p('p135-p138', '依缺損層次與位置比較直接縫合、局部皮瓣與游離移植物，需兼顧血流、閉眼與角膜保護。', '小缺損多一次完成，大缺損可能分期；初期數週癒合，外形與疤痕成熟常需數月。', '目標是安全覆蓋眼球並盡量恢復外觀，不保證完全相同於受傷或切除前。', '可有收縮、缺刻、內外翻或腫瘤相關再處置，少數需修整。');
  p('p139', '依淚小管與眼瞼損傷程度選修復與支架，先排除眼球穿孔，不能只縫皮膚表面。', '傷口常一至數週修復，疤痕需數月，支架留置及拆除依專科計畫。', '可重建排淚與閉眼功能，但嚴重外傷可能仍有流淚或眼瞼形狀差異。', '淚道再狹窄或支架移位可能需調整，勿自行拉管。');
  p('p143', '活動期先評估藥物，穩定後可因突出等需求考慮減壓；視神經受壓威脅視力時則可能需急救式處理。', '術後腫脹常數週減輕，複視及眼球位置需數月評估，後續斜視與眼瞼手術可能分期。', '可增加眼窩空間並減少壓迫，已受損視神經不一定恢復，亦可能新發複視。', '原眼病仍可能活動或有殘留突出，需長期甲狀腺與眼科照護。');
  p('p145', '部分骨折可觀察消腫，若有肌肉嵌頓、功能受限或明顯位置問題則考慮重建，兒童特定夾傷須急處理。', '術後腫脹常數週改善，複視與麻木可能數月才穩定，個別手術時機由傷勢決定。', '可解除嵌頓並改善眼球支撐，神經與肌肉重傷仍可能留複視或感覺改變。', '可能有殘留眼球內陷、複視或植入物問題，少數需再次調整。');
  p('p146', '眼窩腔室症候群威脅視力時屬緊急減壓，不能把等待影像或觀察當作同等替代；之後仍要處理原因。', '搶救按分鐘進行，減壓後持續監測眼壓與視力，傷口與腫脹恢復以數週計。', '目標是減少持續缺血，視力結果取決於受壓多久及原傷勢。', '可能再出血或壓力再升，症狀重現需即刻評估。');
  p('p147', '依膿瘍位置、視力與抗生素反應比較藥物或引流，並與耳鼻喉共同處理鼻竇感染源。', '急性期需立即治療，住院、抗感染與傷口恢復通常數日至數週，嚴重感染可更久。', '及時引流可控制感染及壓迫，但視神經已有損傷時未必完全恢復。', '感染來源未清除可再發，需完成抗感染與鼻竇後續照護。');
  p('p148 p149 p151 p152', '依阻塞位置與年齡比較觀察、探通、氣球、插管或淚囊鼻腔吻合；成人與嬰兒的選擇及自然改善機會不同。', '手術初期恢復通常數週，若留支架可能數週至數月再拆，通暢與流淚需後續評估。', '多能改善適當阻塞型流淚，若合併眼表刺激或眼瞼幫浦問題，仍可能流淚。', '疤痕再狹窄或阻塞持續時可需再次處理。');
  p('p150', '嚴重淚小管阻塞等情況，可比較其他重建與 Jones 管，需先確認能接受長期管路維護。', '置管後初期數週恢復，之後管路清潔、位置與通暢檢查通常需長期持續。', '可建立替代排淚通道，但不是恢復原有正常淚小管，也不能免維護。', '管可阻塞、移位或脫出而需重置或更換。');
  p('p153', '淚點狹窄的擴大與乾眼時的封閉目的相反，必須先確認病因，再選成形、塞子或燒灼。', '多一次門診或小手術，數日至數週評估癒合與流淚變化，之後按症狀追蹤。', '適當選擇可改善排淚或增加保濕，但不能同時解決所有乾眼與流淚原因。', '可能再狹窄、再開通或過度流淚，需要調整或反向處理。');
  p('p154', '依慢性感染、無法重建或腫瘤病因，與重建排淚或其他腫瘤治療比較，切除範圍由病因決定。', '傷口多數週恢復，若有腫瘤則依病理安排數月治療及多年追蹤。', '可移除特定感染源或病灶，但不會自動建立新的排淚通道。', '持續流淚或原腫瘤復發可能需後續處理。');
  p('p156 p157 p181', '在無法安全保留、持續疼痛或特定腫瘤情況，才比較眼球摘除與眼內容剜除；疑似眼內腫瘤通常不能選剜除。', '手術後初期需數週癒合，之後再依組織穩定度配義眼，外觀適應與調整可能數月。', '可處理疼痛、腫瘤或嚴重破壞，義眼與植入物改善外觀，無法恢復被移除眼睛的視力。', '可能有植入物外露、眼窩不適或腫瘤相關風險，需後續照護與心理支持。');
  p('p158 p159 p160', '依眼窩體積、攣縮與義眼需求，比較義眼調整、植入物、真皮脂肪或黏膜重建，先處理感染與活動發炎。', '可能一次或分期手術，初期癒合數週，體積、疤痕與義眼配適穩定常需數月。', '目標是舒適、空間及外觀，組織收縮或移植物吸收會影響結果。', '可能再攣縮、外露或體積變化而需再次調整，長期保養仍重要。');
  p('p161-p169 p171-p175', '依眼位、複視、頭位與肌肉功能，比較配鏡、稜鏡、觀察、特定注射或眼外肌手術；先天或神經病型的目標各不相同。', '若選手術，日常不適常數日到數週改善，紅眼與眼位穩定可能數週至數月；複雜者可能分期。', '可改善正前方眼位、頭位或部分複視，但不一定恢復所有方向活動，也不能代替弱視治療。', '可能殘留、過矯或再偏，需要稜鏡或再次手術；前節血流與角膜保護也需監測。');
  p('p176 p177', '依腫瘤大小與位置比較斑塊、質子或其他放射、局部切除與眼球摘除，需一起考慮保眼、視力與轉移風險。', '斑塊可能留置數日，外部放射依計畫分次；腫瘤反應以數月評估，眼部與全身監測需多年。', '可局部控制腫瘤，但不保證保留原視力，放射性黃斑、視神經或眼壓問題可延遲出現。', '可復發或之後轉移，也可能需處理放射副作用，不能照完就停止追蹤。');
  p('p179', '只適合特定腫瘤及有經驗中心，需與放射或摘除比較，並規劃是否合併其他局部治療。', '通常一次較複雜手術，恢復需數週至數月，之後長期眼部與全身追蹤。', '可在選定情境保留眼球，但出血、視網膜及原腫瘤問題會影響視力。', '有局部復發與播散風險，可能需追加放射、手術或全身治療。');
  p('p182', '廣泛侵襲且其他方法不足時，才評估眼窩內容剜除，並比較適合的保留器官治療與重建。', '傷口與重建常需數週至數月，外觀修復及心理適應更久，腫瘤監測持續多年。', '主要為控制局部惡性病灶，會失去該眼視力與部分眼窩組織，需完整說明重建與生活支持。', '仍可能局部或全身復發，需要腫瘤團隊持續追蹤。');
  p('p183 p184 p185', '依視網膜母細胞瘤分期比較全身、眼動脈與特定眼內給藥，並配合雷射、冷凍或必要摘除；方法不可自行互換。', '多需數月、多次療程與反覆麻醉檢查，完成後仍多年追蹤眼部與全身。', '治療依序重視保命、保眼與視力，保留眼球不代表一定有正常視覺。', '可有殘留播種、新病灶或復發，需要追加局部或全身治療，遺傳追蹤也不能省略。');
  p('p186', '依病灶種類、大小與位置比較冷凍、雷射、局部藥物或其他手術，對惡性病灶常只是整體治療的一部分。', '可一次或分次完成，腫脹數日到數週改善，病灶反應與後續照護以月計。', '可破壞適當局部病灶，但不能保證控制超出冷凍範圍的疾病。', '可能殘留或復發，需依病理與病型決定是否補治療。');
  p('p189 p190', '這些是分期或範圍評估，先確認結果能否改變治療；之後依腫瘤類型比較局部、淋巴結與全身處理。', '採樣多一次完成，傷口數日至數週恢復，病理完整結果可能需數日至數週，腫瘤療程另依結果安排。', '可幫助判斷範圍及風險，不是做完就根治腫瘤；陰性也不能完全排除未取樣部位或未來變化。', '日後病情或可疑區域改變可能需再次評估；前哨陽性或上皮擴散不自動代表同一種大手術。');

  function explain(ids, mechanism) {
    var selected = {};
    assign(selected, mechanism, ids);
    Object.keys(selected).forEach(function (id) {
      if (!diseases[id]) throw new Error('Unknown disease mechanism: ' + id);
      diseases[id] = Object.assign({}, diseases[id], {mechanism: mechanism});
    });
  }
  explain('d53', '眼睛的聚焦力與眼球長度不匹配，遠方影像落在視網膜前方，所以遠看模糊；高度近視還可能把眼底組織拉薄。');
  explain('d54', '影像原本傾向落在視網膜後方，眼睛需要更用力調節來看清楚；兒童調節時也可能帶動眼睛向內偏。');
  explain('d55', '眼睛不同方向的弧度或屈光力不一樣，無法把光線集中成清楚單一影像，因此會模糊或有重影。');
  explain('d57', '兩眼對焦度數不同，可能讓大腦收到清晰度或大小差很多的影像，影響融合與兒童視覺發展。');
  explain('d67 d68 d70 d71 d79 d80 d87 d94 d361', '眼內液體稱為房水，排出阻力或其他壓力負擔可能讓視神經逐步受損；因此治療會著重降低眼壓並追蹤神經功能。');
  explain('d69', '每個視神經能承受的壓力不同，血流與組織耐受等因素也有關，因此量到一般範圍眼壓仍可能發生損害。');
  explain('d72-d77', '虹膜與角膜之間的排水空間變窄或被遮住，房水排不出去就會升壓；急性發作與慢性沾黏的處理時機不同。');
  explain('d97-d103 d105 d305', '水晶體原本負責聚焦，透明度下降後會散射與阻擋光線，所以會模糊、眩光或色彩變淡；成因可包括老化、發育、藥物或其他眼病。');
  explain('d114 d115 d116 d121 d122 d124 d125 d126', '發炎會讓眼內細胞與血管產生反應，造成疼痛、畏光或積液；可能與免疫、感染或外傷有關，有些病例找不到明確誘因。');
  explain('d147-d152', '長期血糖等因素會損害細小血管，造成滲漏、出血或缺血；缺氧嚴重時還可能長出脆弱的新生血管。');
  explain('d153-d155', '靜脈回流受阻會讓局部血液淤積、出血與滲漏，黃斑積液會影響中央視力，缺血則可能刺激新血管。');
  explain('d156 d157', '視網膜動脈的血流突然受阻，常與栓塞有關，感光相關組織得不到足夠氧氣，因此視力或視野會突然消失。');
  explain('d167 d168', '黃斑負責閱讀與辨識細節，支持感光細胞的色素上皮等組織逐漸失能，可形成沉積或萎縮，所以中央視覺受到影響。');
  explain('d169 d171 d172', '不正常的新生血管容易漏水或出血，破壞黃斑的清楚成像；注射主要抑制這些血管的活動。');
  explain('d173 d174', '脈絡膜循環與色素上皮的屏障、排水功能失衡，讓液體積在黃斑下，造成影像變形。');
  explain('d187', '眼內透明的玻璃體隨年齡液化並與視網膜分離，牽拉時可產生閃光，凝聚物會形成飛蚊。');
  explain('d199-d204 d207 d214', '相關基因差異會影響視網膜細胞的功能或存活；桿細胞與夜視、周邊視野有關，錐細胞則與中央視力及色覺有關，不同病型受影響順序不同。');
  explain('d223 d224 d235 d332', '黑色素細胞出現異常、失去正常生長控制而形成惡性病灶；發生部位不同，生物特性與轉移路徑也不同。');
  explain('d228', '兒童視網膜細胞的生長控制出現異常，部分與可遺傳的 RB1 變異有關，因此可能需要家族與另一眼評估。');
  explain('d239 d240 d241', '免疫性發炎會干擾視神經傳遞訊號，有些主要影響保護神經的髓鞘；不同抗體或疾病造成的損傷與復發風險不一樣。');
  explain('d242 d243 d244', '視神經供血不足會使神經纖維缺氧，動脈炎型還涉及血管發炎與阻塞，因此須特別緊急保護另一眼。');
  explain('d264 d265 d266', '控制眼外肌的腦神經訊號受損，使兩眼無法朝同一位置協調，因而看到分開的影像。');
  explain('d289-d293 d295-d297 d299', '雙眼的對焦、肌肉平衡或融合控制不一致，讓眼睛無法同時對準；不同類型不一定是單一肌肉太弱。');
  explain('d318 d319', '眼瞼的腺體阻塞或感染會造成局部腫塊；慢性油脂發炎與急性細菌感染並不相同，所以治療也不同。');
  explain('d333 d334', '免疫反應使眼窩脂肪與眼外肌腫脹，之後可能纖維化，造成突出、複視或閉眼不全，少數壓迫視神經。');
  explain('d349 d350 d309', '眼淚除了製造與停留在表面，也要經淚點、淚小管與鼻淚管排出；通道阻塞或發炎時會流淚、分泌物增加或感染。');
  explain('ird-ad-rp ird-rpgr-xlrp ird-rp2-xlrp ird-rpe65 ird-cep290 ird-aipl1 ird-gucy2d ird-crb1 ird-rdh12 ird-nmnat1 ird-tulp1 ird-hjmd ird-dram2 ird-lord ird-stgd3 ird-stgd4 ird-doyne ird-ncmd ird-cacd ird-arb ird-imp-vitelliform ird-enhanced-s-cone ird-kcnv2 ird-bradyopsia ird-bornholm ird-oligocone ird-blue-cone ird-xl-csnb-complete ird-xl-csnb-incomplete ird-ar-csnb ird-riggs-csnb ird-bothnia ird-sveinsson ird-crx ird-cdhr1 ird-cerkl ird-pcare ird-poc1b ird-mak ird-slc7a14 ird-imdh1 ird-best1-advrc', '視網膜把光線轉成大腦可使用的訊號，相關基因或發育差異會影響感光細胞、支持細胞或訊號傳遞，所以可能有夜視、中央視力或色覺問題。');
  explain('ird-lhon ird-dnajc30-lhon ird-opa1 ird-opa1-plus ird-wfs1 ird-opa3 ird-tmem126a ird-aco2 ird-rtn4ip1 ird-ssbp1 ird-nr2f1', '視神經負責把眼睛訊號傳到大腦，基因或發育相關異常使神經纖維功能不足或逐漸受損，因此中央視力與色覺可能下降。');

  function steps(ids, preparation, immediateCare, aftercare) {
    var selected = {};
    assign(selected, preparation, ids);
    Object.keys(selected).forEach(function (id) {
      if (!procedures[id]) throw new Error('Unknown procedure flow: ' + id);
      if (procedures[id].preparation) throw new Error('Duplicate procedure flow: ' + id);
      procedures[id] = Object.assign({}, procedures[id], {preparation: preparation, immediateCare: immediateCare, aftercare: aftercare});
    });
  }
  steps('p0 p1 p2 p3 p4 p6 p7', '先量測度數與眼球資料，檢查眼底並選擇鏡片；與團隊確認麻醉及原本用藥，是否禁食依安排。', '檢查傷口、眼壓及鏡片狀況，交代眼藥與護罩使用，並預約初期回診。', '按處方點藥、避免揉眼及髒水入眼；游泳、重物與劇烈活動何時恢復依檢查決定。若疼痛或紅眼加重、視力突然下降，當日聯絡眼科。');
  steps('p5', '由兒童眼科評估視軸與弱視，討論麻醉、鏡片及術後矯正方式，家長需了解接觸鏡或遮眼安排。', '確認傷口、視軸與眼壓，開始適齡光學矯正及弱視計畫，再安排密集追蹤。', '照顧者協助點藥、避免揉眼，按時戴鏡及完成指定弱視治療；紅痛、畏光或孩子明顯不願睜眼須提早檢查，並長期量眼壓。');
  steps('p8 p9', '同時評估白內障、隅角及青光眼目標眼壓，討論合併方式與手術前後眼藥如何調整。', '檢查鏡片、前房、眼壓及實際引流效果，依結果安排較密集回診。', '降眼壓與抗發炎眼藥是否繼續，須依個別處方，不能自行全部停用；不揉眼或自行按摩濾泡，疼痛、變糊或傷口滲漏要回診。');
  steps('p10-p16 p93', '先檢查角膜、剩餘囊袋與眼底，討論保留、取出或更換鏡片，以及是否需玻璃體手術。', '確認鏡片位置、傷口與眼壓，後續比較黃斑、角膜及度數是否穩定。', '按時點藥並避免碰撞；新重影、鏡片晃動感、閃光或黑幕要提早檢查。需配鏡時等待度數穩定，若眼內有氣體另遵守氣泡限制。');
  steps('p17 p101', '確認視力下降來自後囊混濁，檢查眼壓、鏡片位置與眼底，依需要散瞳及點局部麻醉。', '完成後依風險量眼壓，交代短期眼藥與回診，當天視力未清楚前不要自行駕車。', '短暫飛蚊或模糊可出現；若飛蚊突然大增、閃光、黑幕、持續疼痛或視力下降，立即回眼科，不能只當作正常雷射反應。');
  steps('p18', '這通常是原手術中需要的安全處理；醫師先穩定前房並確認玻璃體脫出與囊袋損傷程度。', '確認玻璃體不再拉扯傷口，決定鏡片放置或分期方式，再安排較密集術後檢查。', '依處方點藥，注意眼壓與黃斑變化；新閃光、黑幕、疼痛或視力惡化應提早回診，可能需後續視網膜評估。');
  steps('p19 p20', '評估哪一層角膜受損、眼壓與眼底，安排合適捐贈組織並說明縫線、散光及排斥風險。', '檢查移植物、傷口與眼壓，安排抗排斥眼藥和後續縫線管理。', '抗排斥眼藥不可自行停用；避免揉眼與撞擊，使用適當防護。鬆線、紅、痛、畏光或視力下降即使多年後也要當日聯絡角膜團隊。');
  steps('p21 p22', '確認內皮失能與其他角膜狀況，討論移植方式、氣泡姿勢及可能的補氣需求。', '確認移植物方向、貼附與眼壓，交代指定姿勢、眼藥與初期複查。', '依指定姿勢與時間照護，不自行減停抗排斥藥；若變得更模糊、疼痛或噁心須急查眼壓與貼附。氣泡未完全吸收前另遵守飛行與麻醉限制。');
  steps('p23', '評估一般移植為何不適合，確認視網膜、視神經與眼壓，以及能否負擔長期眼表與感染照護。', '檢查人工角膜與周圍組織，依型別安排必要眼藥、保護鏡片與眼壓追蹤。', '嚴格依專科計畫長期點藥與回診，不自行取下指定鏡片；分泌物增多、疼痛、滲漏或視力改變需立即檢查。');
  steps('p24 p25', '以地形圖與厚度確認進展與安全條件，說明所選方案及上皮是否需移除。', '檢查表皮與角膜，必要時放保護鏡片並安排早期傷口追蹤。', '保護鏡片由醫師決定拆除，不自行拉出；按處方點藥、避免揉眼與碰水。疼痛反而加重、白點或視力驟降要提早回診。');
  steps('p26', '檢查角膜形狀、厚度與清晰度，討論環段位置及是否另需交聯或特殊鏡片。', '確認環段位置、切口及眼壓，安排眼藥與地形追蹤。', '避免揉眼與碰撞，暫停接觸鏡依驗配安排恢復；局部紅痛、異物感加重或環段似乎外露須儘速檢查。');
  steps('p27 p28 p29 p37', '先確認破皮或混濁的位置與深度，排除感染並討論選用的表面處置。', '檢查新表皮與傷口，依需要安排保護鏡片、眼藥及早期複查。', '上皮未完整前避免揉眼、髒水及自行配戴鏡片；保護鏡片不自行取出。疼痛、畏光加重或出現白點需回診。');
  steps('p30 p95 p144 p155 p180', '先確認採樣要回答什麼問題，以影像規劃安全路徑並交代麻醉與出血相關用藥。', '團隊將檢體送合適檢驗，確認傷口與視功能，安排解讀報告及下一階段治療。', '按處方照顧傷口及點藥，務必回診看完整結果；檢體不足可能需重採。疼痛、突出、出血不止或視力變差應儘速聯絡團隊。');
  steps('p31 p32', '確認眼表缺損或病灶範圍，先處理相關發炎，討論移植物與固定方式。', '檢查移植物與表皮覆蓋，交代眼藥、必要的保護鏡片及回診時程。', '避免揉眼、髒水與自行拉除縫線或鏡片；依處方點藥。翼狀贅片術後持續防曬，紅痛、白點或視力下降需回診。');
  steps('p33', '先穩定眼表與眼瞼，評估單雙眼病變與供體，說明是否需全身免疫藥及分期角膜重建。', '檢查移植上皮與眼表，依來源安排局部及可能的全身用藥與檢驗。', '按期追蹤表皮、眼壓及全身藥物安全，不自行停免疫藥；新的紅痛、破皮或感染症狀需及早聯絡，後續視力重建需等眼表穩定。');
  steps('p34 p35', '先確認滲漏、穿孔大小與感染原因，視急迫性選擇暫時封閉或較完整修補。', '確認封閉效果與眼球形態，安排短期密集檢查及後續是否需移植。', '不要揉壓眼球或自行拉除組織膠、鏡片與縫線；若滲漏、疼痛、混濁或視力惡化需即刻回診，仍要完成原病因治療。');
  steps('p36 p140 p141', '確認閉眼不足的原因與角膜風險，討論保留多少眼裂、是否暫時，以及配重或其他方式的取捨。', '檢查閉眼與角膜保護，確認仍能按指示點藥及檢查，預約縫線或材料追蹤。', '持續依指示潤滑，避免拉扯縫線或植入處；不能因眼裂變小就停眼表照護，疼痛、角膜白點或材料外露需提早回診。');
  steps('p38', '新發紅、痛、畏光或變糊需當日檢查，先區分排斥、感染與眼壓問題。', '開始相應密集治療後，短期檢查透明度、表皮、發炎與眼壓，再調整藥量。', '嚴格依處方點藥，不能自行突然停類固醇；若反而更痛或更糊要立即聯絡，之後仍按醫師指示慢慢減藥與長期追蹤。');
  steps('p39 p40', '確認傷口與移植物穩定，用驗光及地形圖決定縫線或散光調整範圍。', '檢查傷口完整、眼壓及角膜形狀，依實際處置安排眼藥和下次驗光。', '不自行拉縫線或急著換最終眼鏡；避免揉眼與碰撞，突然異物感、漏水、紅痛或視力下降需回診。');
  steps('p41 p191', '確認度數穩定，完成角膜形狀、厚度與乾眼評估，討論遠近用眼及術後配合事項。', '確認角膜瓣或小切口、視軸與眼表，交代眼藥及早期回診。', '不揉眼、依指示點藥，游泳、眼妝及接觸運動依檢查安排恢復；疼痛加重或視力突然下降須急查，乾眼與夜視問題也要主動回報。');
  steps('p42 p43', '確認度數、角膜安全厚度與眼表，說明初期疼痛、保護鏡片及較慢的視力恢復。', '確認表面切削區與保護鏡片，安排癒合期間眼藥與早期檢查。', '不要自行移除保護鏡片或減停處方藥，避免揉眼及不潔水；戶外依指示防曬，疼痛反增、白點或視力下降要回診。');
  steps('p44 p45 p46 p47', '完成角膜、內皮、前房與眼底評估，依術式確認鏡片、度數與近用需求。', '檢查傷口、眼壓與實際鏡片或切口狀態，安排短期驗光及追蹤。', '按時點藥、避免揉眼與碰撞；有植入鏡片者依安排長期追蹤內皮與眼壓，突然光暈、頭痛、噁心或變糊要及時檢查。');
  steps('p48 p49 p50 p51 p52', '先釐清原手術紀錄及現在問題，用角膜影像區分度數、植入物、瓣或擴張病因。', '依是否實際用藥或手術，確認眼表、角膜與眼壓，安排後續穩定度評估。', '勿自行使用舊類固醇或尋求反覆追加雷射；依實際處置照護傷口與鏡片，新疼痛或視力惡化須提早檢查。');
  steps('p53-p62', '評估目標眼壓、結膜與既往手術，說明選定通路或引流管及手術前後眼藥。', '檢查前房、引流功能、傷口與眼壓，依結果安排初期密集回診及調藥。', '不自行停降眼壓藥、按摩眼球或拉扯縫線，依指示避免用力與碰撞；滲漏、管路外露、紅痛或突然變糊需即時聯絡。');
  steps('p63-p68', '確認隅角可見度、目標眼壓與是否合併白內障，討論實際切開、擴張或植入方式。', '檢查眼壓、前房出血及隅角處置結果，安排眼藥及早期回診。', '眼藥是否繼續要依處方，不因傷口小就自行停藥或提前劇烈活動；疼痛、噁心或視力突然變差應回診。');
  steps('p69-p72 p104', '依剩餘視功能、疼痛與眼壓選能量方案，討論麻醉、預期反應與可能需重複。', '觀察眼壓與發炎，交代止痛、抗發炎及降眼壓藥如何使用，再按期評估效果。', '不要自行停原降眼壓藥或過量追加；疼痛反而加劇、視力下降或明顯紅腫需提早檢查，降壓效果需依量測判斷。');
  steps('p73 p74', '完成兒童眼球及視神經評估，討論全身麻醉、手術方式及術後視覺發展照護。', '檢查眼壓、角膜與傷口，安排門診或必要的麻醉下複查。', '照顧者協助用藥、配鏡與防揉眼；畏光、角膜混濁、明顯不適或眼球再變大需提早檢查，後續也要追蹤弱視。');
  steps('p75 p76 p77 p102', '先找出濾泡阻塞、滲漏或流量異常的原因，再選針撥、拆線、縫補或其他修正。', '再次確認眼壓、前房深度與傷口是否滲漏，安排數日內或依風險更早複查。', '處置後眼壓可能快速改變，不自行按摩或調藥；紅痛、漏水、頭痛噁心或視力惡化需即刻聯絡，後續可能仍要調整引流。');
  steps('p78-p92 p94', '用散瞳與影像確認視網膜、出血及牽引，討論實際術式、氣體或矽油及術後姿勢。', '確認視網膜與眼壓，交代填充物、指定姿勢、眼藥和早期回診安排。', '依指示點藥、護眼與維持姿勢，避免揉眼、碰撞及未核准的劇烈活動；新黑幕、疼痛加重或視力驟降須立即回診，有氣泡時另遵守飛行與麻醉限制。');
  steps('p96 p118', '確認藥物、眼別與病因，檢查是否有感染，完成眼表消毒及局部麻醉。', '依需要確認視網膜灌流與眼壓，交代短期反應及下一次眼底評估或治療。', '避免揉眼與不潔水，一般不常規使用預防性抗生素；疼痛、紅眼、畏光加重或視力下降應當日急查，不能等下次注射。');
  steps('p97 p98', '先確認隅角閉鎖機轉及眼壓，依需要用藥、局部麻醉與接觸鏡定位。', '檢查雷射反應、眼壓與開口或隅角效果，交代短期眼藥及回診。', '不要自行停原眼藥或加縮瞳藥，光暈、頭痛、噁心與變糊加劇需及時檢查；之後仍要確認隅角與另一眼風險。');
  steps('p99 p100', '確認開放隅角與適合雷射的排水構造，討論原本眼藥是否繼續，點麻醉並用接觸鏡定位。', '依風險檢查眼壓並安排短期追蹤，數週後比較真正降壓效果。', '依指示用藥，不因做完雷射就自行停藥；持續疼痛、明顯紅眼或視力下降需回診。');
  steps('p103', '先散瞳排除裂孔並確認混濁離鏡片與視網膜的位置，討論觀察、雷射與手術的取捨。', '檢查視覺反應與眼壓，安排是否需追加或繼續觀察。', '飛蚊不一定立刻完全消失；新閃光、大量飛蚊、黑幕或疼痛要立即檢查。');
  steps('p105 p106 p107 p108 p110 p178', '用眼底及影像確認治療區域與目標，依需要散瞳、點麻醉及定位，說明是否分次完成。', '確認處置範圍與不適，安排後續眼底或影像比較，而非只看當天視力。', '依視力狀況安排返家交通與活動，按指定日期追蹤；新黑幕、持續劇痛或視力明顯下降應急查，原疾病仍可能需其他治療。');
  steps('p109', '先用影像確認病灶，核對光敏感藥與照射計畫，安排靜脈給藥。', '檢查眼部與注射處狀況，明確交代避光期間及後續影像評估。', '依產品與團隊指定時間避強光，不自行只以防曬乳替代保護；新的視力惡化或注射處疼痛腫脹需聯絡，病灶仍需回診比較。');
  steps('p111', '確認是診斷取樣或緊急降壓，完成消毒、麻醉與必要檢驗安排，避免不必要的眼內操作。', '檢查傷口閉合、前房、灌流與眼壓，安排檢體結果或壓力原因的後續處理。', '依指示用藥，不揉壓眼球；疼痛、紅眼、漏水或視力下降要及時回診，暫時降壓不能取代病因治療。');
  steps('p112', '詢問金屬敲擊等受傷機轉，確認沒有穿透傷後，以局部麻醉定位異物。', '檢查是否有殘留異物與表皮傷口，安排必要眼藥及癒合追蹤。', '暫停接觸鏡、不自行使用麻醉眼藥，按指示點藥；疼痛未減、白點變大或視力變差需回診，回工作時持續護目。');
  steps('p113 p132', '確認像一般霰粒腫，反覆或不典型者討論病理，再選刮除或注射及局部麻醉。', '檢查出血與傷口，交代清潔、眼藥與病理回診需求。', '不擠壓殘留硬塊，依指示清潔與保養眼瞼；紅腫擴大、發燒、傷口不癒或同處再次長出需回診。');
  steps('p114', '先評估乾眼、眼表發炎與排淚通道，討論可移除或較永久的處置。', '確認塞子位置或封閉處狀況，再評估保濕與流淚是否改善。', '不要搓揉或自行拔塞子，原有乾眼治療依指示繼續；持續流淚、內眼角紅痛或分泌物增多應回診。');
  steps('p115 p142 p170', '確認症狀與要作用的肌肉、產品及劑量，告知吞嚥呼吸問題與相關神經肌肉病史。', '說明藥效並非立即出現，安排效果、眼瞼位置與複視的追蹤。', '不自行揉壓注射處或加做其他注射，依指示保護眼表；閉眼不足、嚴重複視需聯絡，若吞嚥或呼吸困難立即急診。');
  steps('p116', '確認病因、藥物與眼周層次，完成消毒及適當麻醉，並說明長效製劑的監測需求。', '檢查眼壓、眼球與局部反應，交代回診及原眼藥如何使用。', '避免揉壓，疼痛、紅眼或視力下降需及時回診；若為類固醇注射，即使感覺良好也要依安排量眼壓。');
  steps('p117 p130', '找出倒睫範圍與是否合併眼瞼內翻，說明拔除、毛囊或眼瞼處置的差別。', '檢查角膜摩擦與局部反應，安排眼表用藥與再生情況追蹤。', '不要自行拔、燒或擠毛囊，按指示潤滑與清潔；持續痛、畏光或白點需檢查角膜。');
  steps('p119-p129 p131', '測量眼瞼、眉位、閉眼與眼表；若需手術，討論切口、對稱度、麻醉及出血相關藥物。', '檢查眼瞼位置、閉眼與角膜，安排傷口、縫線及後續高度評估。', '依手術指示冷敷、清潔與塗藥，不自行壓揉傷口；眼睛閉不緊需潤滑，劇痛、迅速腫大或視力下降須立即就醫。');
  steps('p133-p138', '先確認病灶與病理或缺損範圍，討論邊界控制、重建與是否分期。', '檢查傷口、皮瓣或移植物血流及角膜保護，安排病理結果與下一階段治療。', '依指示清潔塗藥，不拉扯皮瓣、移植物或縫線；兒童暫時遮住視軸時須有弱視計畫。感染、組織變色或視力下降應提早聯絡。');
  steps('p139', '先排除眼球傷，確認眼瞼與淚小管範圍，討論修復、麻醉及支架。', '檢查眼瞼邊緣、閉眼與支架位置，安排傷口與後續拆管追蹤。', '不揉眼或拉支架，依指示清潔用藥；支架移位、持續流血、紅痛或閉眼不足須聯絡團隊。');
  steps('p143', '評估活動度、眼窩影像、視神經與複視，確認是否緊急救視力或穩定期重建。', '檢查視力、瞳孔、眼壓與眼球運動，依手術路徑安排鼻腔及眼部照護。', '避免擤鼻及未核准的劇烈活動，按指示護眼；劇痛、迅速突出、視力或色覺下降需立即就醫，後續可能分期調整複視與眼瞼。');
  steps('p145', '以影像與眼球運動檢查確認骨折及嵌頓，討論手術時機與植入物。', '確認視力、眼球活動與位置，安排腫脹、複視及神經感覺追蹤。', '避免擤鼻與碰撞，依指示用藥；視力下降、劇痛、持續噁心或腫脹突然增加要立即回診。');
  steps('p146', '臨床高度懷疑威脅視力的眼窩高壓時立即處理，不為等影像而延誤。', '立刻重新確認眼窩張力、眼壓與視力，必要時進一步減壓並處理出血來源。', '需持續監測再出血與視神經，不自行壓眼；新突出、劇痛或視力惡化要即刻處理，傷口修復時機另由團隊安排。');
  steps('p147', '緊急影像確認膿瘍與鼻竇病因，先給適當抗生素並評估引流路徑。', '追蹤視力、眼球運動、發燒與培養結果，再調整抗生素及鼻竇治療。', '完成整個抗感染療程與追蹤，不能退燒就停藥；再發眼球轉動痛、突出或視力變差需立即就醫。');
  steps('p148 p149 p151 p152', '確認阻塞位置、鼻腔與年齡相關條件，選探通、擴張或重建，並交代麻醉與是否插管。', '檢查排淚與局部出血，安排眼藥、必要鼻腔照護及支架追蹤。', '不自行拉管，若有鼻腔造口依指示避免擤鼻；持續出血、紅痛、發燒或支架移位須回診，拆管時間依個別計畫。');
  steps('p150', '確認原淚小管無法正常使用，討論替代玻璃管與長期維護需求。', '確認管位與排淚，教導適合的清潔並安排固定與通暢檢查。', '不自行拔管或用器械通管，依指示長期清潔；脫出、堵塞、出血或疼痛須聯絡團隊，部分情況需更換。');
  steps('p153', '先辨別需要擴大淚點，還是為乾眼減少排淚，再選正確方向的處置。', '評估局部傷口、保濕與排淚變化，安排是否需調整。', '不揉壓或自行拔塞子；持續過度流淚、乾痛或分泌物需回診，後續依症狀確認是否再狹窄或再開通。');
  steps('p154', '先確認慢性感染或腫瘤等原因，以影像及必要病理規劃切除範圍。', '檢查傷口並追蹤病理，依結果安排其他腫瘤或排淚相關照護。', '保持傷口清潔、依指示用藥；持續紅腫、流血或腫塊需回診，有腫瘤者不可省略後續分期與監測。');
  steps('p156-p160 p181', '確認疼痛、腫瘤或眼窩問題及不可逆的視覺狀態，討論植入物、重建、義眼與心理支持。', '檢查傷口與植入處，依情況保留眼窩模具，安排病理及後續義眼配適。', '不自行提早取出模具或拉縫線，依指示清潔與塗藥；疼痛加重、惡臭分泌物、出血或植入物外露需回診，腫瘤相關者仍需全身監測。');
  steps('p161-p169 p171-p175', '完整測量眼位、頭位、雙眼功能與既往手術，討論實際肌肉與是否需分期或可調縫線。', '檢查眼位、角膜與眼球運動，若使用可調縫線則按計畫調整，再安排穩定度追蹤。', '依指示點藥、避免揉眼與游泳，複視未穩定時不要駕駛；劇痛或視力下降須急查，兒童配鏡及弱視治療仍要持續。');
  steps('p176 p177', '由眼腫瘤與放射團隊完成定位及劑量計畫，說明照射次數、保眼與全身追蹤目標。', '斑塊依計畫取出或完成外部照射後，安排眼底、眼壓與腫瘤大小比較。', '遵守實際放射防護與傷口指示，不能自行套用其他病人的限制；定期監測延遲眼底與眼壓副作用，以及腫瘤與轉移風險。');
  steps('p179', '評估腫瘤位置、分期與保眼可行性，討論切除路徑及可能合併放射或視網膜處理。', '確認出血控制與視網膜、傷口狀態，追蹤病理及是否需追加治療。', '按指示點藥、護眼及維持必要姿勢；新痛或視力驟降需回診，長期腫瘤與全身監測不能省略。');
  steps('p182', '完整分期並討論可替代療法、切除及重建範圍，安排生活與心理支持。', '檢查傷口及重建組織，依病理規劃其他治療與後續外觀修復。', '依團隊教導換藥與保持清潔，不自行移除填塞或拉扯組織；發燒、惡臭分泌物、持續出血需即刻聯絡，並持續腫瘤追蹤。');
  steps('p183 p184 p185', '由兒童眼腫瘤與兒科團隊確認分期、給藥路徑、麻醉及必要全身檢驗，再安排療程。', '檢查眼部腫瘤反應與藥物副作用，依路徑安排全身、血管或眼內相關監測。', '依指定療程與麻醉檢查回診，注意感染、發燒、活動力下降或眼部異常，按腫瘤團隊急症計畫就醫；長期追蹤另一眼與遺傳相關風險。');
  steps('p186 p187 p188', '確認病理、範圍及是否合併其他腫瘤治療，說明局部處置或藥物的步驟與週期。', '檢查眼表與局部組織，追蹤病理或影像，確認後續藥物與追加治療計畫。', '依處方週期點藥或照顧傷口，不自行加濃、延長或重複化療眼藥；持續痛、破皮、白點或視力下降需回診，仍要監測腫瘤復發。');
  steps('p189', '確認腫瘤與淋巴結狀態，團隊安排示蹤定位，說明採樣能提供的分期資訊與風險。', '檢查傷口與顏面神經功能，等待完整病理後由腫瘤團隊討論下一步。', '依指示照護切口，腫脹、流血、發燒或新臉部無力需聯絡；陰性結果也要持續腫瘤與淋巴結監測。');
  steps('p190', '先翻眼瞼與檢查病灶範圍，說明多點採樣及其如何影響後續治療。', '檢查眼表並將各處檢體分別檢驗，完整結果回診後再確認治療範圍。', '依指示點藥與潤滑，不揉眼；紅痛加劇或視力變差須回診，務必看完整報告，檢體不足或後來可疑區域可能需再採樣。');

  root.QUICK_REFERENCE_PATIENT_EDUCATION_ZH = {diseases: diseases, procedures: procedures};
})(typeof window !== 'undefined' ? window : globalThis);
